NAME = 'TpiKJPB: King Jems Pisin Baibel'
BOOK = 'I Chronicles'

CHAPTERS = {
    1: {
        1: '¶ Adam, Set, Inos,',
        2: 'Kenan, Mahalaliel, Jeret,',
        3: 'Henok, Metusela, Lamek,',
        4: 'Noa, Siem, Ham, na Jafet.',
        5: 'Ol pikinini man bilong Jafet, Gomer, na Megok, na Madai, na Javan, na Tubal, na Mesek, na Tiras.',
        6: 'Na ol pikinini man bilong Gomer, Askenas, na Rifat, na Togarma.',
        7: 'Na ol pikinini man bilong Javan, Ilaisa, na Tarsis, Kitim, na Dodanim.',
        8: 'Ol pikinini man bilong Ham, Kus, na Misraim, Put, na Kenan.',
        9: 'Na ol pikinini man bilong Kus, Siba, na Havila, na Sapta, na Reama, na Sapteka. Na ol pikinini man bilong Reama, Siba, na Dedan.',
        10: 'Na Kus i kamapim Nimrot. Em i stat long stap strongpela antap long dispela graun.',
        11: 'Na Misraim i kamapim Ludim, na Anamim, na Lehabim, na Naftuhim,',
        12: 'Na Patrusim, na Kasluhim, (ausait long husat ol Filistin i kam,) na Kaptorim.',
        13: 'Na Kenan i kamapim Saidon, namba wan pikinini bilong em, na Het,',
        14: 'Man Jebus tu, na man Amor, na man Girga,',
        15: 'Na man Hiv, na man Ark, na man Sini,',
        16: 'Na man Arvat, na man Sema, na man Hemat.',
        17: 'Ol pikinini man bilong Siem, Ilam, na Asur, na Arfaksat, na Lut, na Aram, na Us, na Hul, na Geter, na Mesek.',
        18: 'Na Arfaksat i kamapim Sela, na Sela i kamapim Eber.',
        19: 'Na long Eber meri i karim tupela pikinini man, nem bilong wanpela em i Pelek, bilong wanem, long ol de bilong em dispela graun i bruk. Na nem bilong brata bilong en em i Joktan.',
        20: 'Na Joktan i kamapim Almodat, na Selep, na Hasarmavet, na Jera,',
        21: 'Hadoram tu, na Usal, na Dikla,',
        22: 'Na Ebal, na Abimel, na Siba,',
        23: 'Na Ofir, na Havila, na Jobap. Olgeta dispela em i ol pikinini man bilong Joktan.',
        24: 'Siem, Arfaksat, Sela,',
        25: 'Eber, Pelek, Reu,',
        26: 'Seruk, Nehor, Tera,',
        27: 'Ebram, dispela yet em i Ebraham.',
        28: '¶ Ol pikinini man bilong Ebraham, Aisak, na Ismel.',
        29: 'Ol dispela em ol lain tumbuna bilong ol. Namba wan pikinini bilong Ismel, Nebaiot, nau Kedar, na Atbel, na Mipsam,',
        30: 'Misma, na Duma, Masa, Hedat, na Tema,',
        31: 'Jetur, Nafis, na Kedema. Ol dispela em ol pikinini man bilong Ismel.',
        32: 'Nau ol pikinini man bilong Ketura, namba tu lain meri bilong Ebraham. Em i karim Simran, na Joksan, na Medan, na Midian, na Isbak, na Sua. Na ol pikinini man bilong Joksan, Siba, na Dedan.',
        33: 'Na ol pikinini man bilong Midian, Ifa, na Efer, na Henok, na Abida, na Eldea. Olgeta dispela em ol pikinini man bilong Ketura.',
        34: 'Na Ebraham i kamapim Aisak. Ol pikinini man bilong Aisak, Iso na Isrel.',
        35: 'Ol pikinini man bilong Iso, Elifas, Reuel, na Jeus, na Jealam, na Kora.',
        36: 'Ol pikinini man bilong Elifas, Timan, na Omar, na Sefi, na Gatam, Kenas, na Timna, na Amalek.',
        37: 'Ol pikinini man bilong Reuel, Nahat, Sera, Sama, na Misa.',
        38: 'Na ol pikinini man bilong Sir, Lotan, na Sobal, na Sibeon, na Ana, na Dison, na Eser, na Disan.',
        39: 'Na ol pikinini man bilong Lotan, Hori, na Homam. Na Timna em i susa bilong Lotan.',
        40: 'Ol pikinini man bilong Sobal, Alian, na Manahat, na Ebal, Sefi, na Onam. Na ol pikinini man bilong Sibeon, Ea, na Ana.',
        41: 'Ol pikinini man bilong Ana, Dison. Na ol pikinini man bilong Dison, Amram, na Es-ban, na Itran, na Keran.',
        42: 'Ol pikinini man bilong Eser, Bilhan, na Savan, na Jakan. Ol pikinini man bilong Disan, Us, na Aran.',
        43: 'Nau ol dispela em ol king husat i bosim kingdom long dispela hap bilong Idom bipo long wanpela king i bosim kingdom antap long ol pikinini bilong Isrel, Bela, pikinini man bilong Beor. Na nem bilong biktaun bilong en em i Dinhaba.',
        44: 'Na taim Bela i dai pinis, Jobap, pikinini man bilong Sera bilong Bosra i kisim ples bilong em na bosim kingdom.',
        45: 'Na taim Jobap i dai pinis, Husam bilong hap bilong ol lain Timan i kisim ples bilong em na bosim kingdom.',
        46: 'Na taim Husam i dai pinis, Hedat, pikinini man bilong Bedat, husat i paitim Midian long ples kunai bilong Moap, i kisim ples bilong em na bosim kingdom. Na nem bilong biktaun bilong en em i Avit.',
        47: 'Na taim Hedat i dai pinis, Samla bilong Masreka i kisim ples bilong em na bosim kingdom.',
        48: 'Na taim Samla i dai pinis, Saul bilong Rehobot klostu long riva i kisim ples bilong em na bosim kingdom.',
        49: 'Na taim Saul i dai pinis, Beal-hanan, pikinini man bilong Akbor, i kisim ples bilong em na bosim kingdom.',
        50: 'Na taim Beal-hanan i dai pinis, Hedat i kisim ples bilong em na bosim kingdom. Na nem bilong biktaun bilong en em i Pai. Na nem bilong meri bilong en em i Mehetabel, pikinini meri bilong Matret, pikinini meri bilong Mesahap.',
        51: 'Hedat tu i dai pinis. Na ol hetman bilong Idom i stap olsem, hetman Timna, hetman Alaia, hetman Jetet,',
        52: 'Hetman Aholibama, hetman Ila, hetman Pinon,',
        53: 'Hetman Kenas, hetman Timan, hetman Mipsar,',
        54: 'Hetman Makdiel, hetman Iram. Ol dispela em i ol hetman bilong Idom.',
    },
    2: {
        1: '¶ Ol dispela em ol pikinini man bilong Isrel, Ruben, Simion, Livai, na Juda, Isakar, na Sebyulan,',
        2: 'Dan, Josep, na Benjamin, Naptalai, Gat, na Aser.',
        3: 'Ol pikinini man bilong Juda, Er, na Onan, na Sela. Dispela tripela, pikinini meri bilong meri Kenan Sua i karim long em. Na Er, namba wan pikinini bilong Juda, em i nogut long ai bilong BIKPELA. Na Em i kilim em i dai.',
        4: 'Na Temar, tambu pikinini meri bilong em, i karim long em Fares na Sera. Olgeta pikinini man bilong Juda em i faipela.',
        5: 'Ol pikinini man bilong Fares, Hesron, na Hamul.',
        6: 'Na ol pikinini man bilong Sera, Simri, na Etan, na Heman, na Kalkol, na Dara, faipela bilong ol olgeta.',
        7: 'Na ol pikinini man bilong Karmi, Ekar, man bilong givim wari long Isrel, husat i kalapim lo long samting i tambu olgeta.',
        8: 'Na ol pikinini man bilong Etan, Asaraia.',
        9: 'Ol pikinini man tu bilong Hesron, husat meri i karim long em, Jeramel, na Ram, na Kelubai.',
        10: 'Na Ram i kamapim Aminadap. Na Aminadap i kamapim Nason, hetman bilong ol pikinini bilong Juda.',
        11: 'Na Nason i kamapim Salma, na Salma i kamapim Boas,',
        12: 'Na Boas i kamapim Obet, na Obet i kamapim Jesi,',
        13: 'Na Jesi i kamapim namba wan pikinini bilong em Eliap, na Abinadap namba tu, na Sima namba tri,',
        14: 'Netanel namba foa, Radai namba faiv,',
        15: 'Osem namba sikis, Devit namba seven.',
        16: 'Husat ol susa bilong ol em i Seruaia, na Abigel. Na ol pikinini man bilong Seruaia, Abisai, na Joap, na Asahel, tripela.',
        17: 'Na Abigel i karim Amasa. Na papa bilong Amasa em i man Ismel Jeter.',
        18: '¶ Na Kelep, pikinini man bilong Hesron, i kamapim ol pikinini long meri bilong em Asuba, na long Jeriot. Ol pikinini man bilong en em i ol dispela, Jeser, na Sobap, na Ardon.',
        19: 'Na taim Asuba i dai pinis, Kelep i kisim bilong em Efrat, husat i karim Hur long em.',
        20: 'Na Hur i kamapim Uri, na Uri i kamapim Besalel.',
        21: 'Na bihain long en Hesron i go long pikinini meri bilong Makir, papa bilong Gileat, husat em i maritim taim em i gat 60 krismas. Na em i karim Segup long em.',
        22: 'Na Segup i kamapim Jair, husat i gat 23 biktaun insait long hap bilong Gileat',
        23: 'Na em i kisim Geser, na Aram, wantaim ol taun bilong Jair, long ol, wantaim Kenat, na ol taun bilong en, yes, 60 biktaun. Olgeta dispela i bilong ol pikinini man bilong Makir, papa bilong Gileat',
        24: 'Na bihain long Hesron i dai pinis long Kelep-efrata, nau Abia, meri bilong Hesron, i karim long em Asur, papa bilong Tekoa.',
        25: 'Na ol pikinini man bilong Jeramel, namba wan pikinini bilong Hesron, em, Ram, namba wan pikinini, na Buna, na Oren, na Osem, na Ahaisa.',
        26: 'Jeramel tu i gat narapela meri, husat nem bilong en em i Atara. Em i mama bilong Onam.',
        27: 'Na ol pikinini man bilong Ram, namba wan pikinini bilong Jeramel, em, Meas, na Jamin, na Eker.',
        28: 'Na ol pikinini man bilong Onam em, Samai, na Jada. Na ol pikinini man bilong Samai, Nedap, na Abisur.',
        29: 'Na nem bilong meri bilong Abisur em i Abihail, na em i karim Aban long em, na Molit.',
        30: 'Na ol pikinini man bilong Nedap, Selet, na Apaim. Tasol Selet i dai pinis na em i no gat pikinini.',
        31: 'Na ol pikinini man bilong Apaim, Isi. Na ol pikinini man bilong Isi, Sesan. Na ol pikinini bilong Sesan, Alai.',
        32: 'Na ol pikinini man bilong Jada, brata bilong Samai, Jeter, na Jonatan. Na Jeter i dai pinis na em i no gat pikinini.',
        33: 'Na ol pikinini man bilong Jonatan, Pelet, na Sasa. Ol dispela em i ol pikinini man bilong Jeramel.',
        34: 'Nau Sesan i no gat ol pikinini man, ol pikinini meri tasol. Na Sesan i gat wanpela wokboi, wanpela man Isip, husat nem bilong en em i Jarha.',
        35: 'Na Sesan i givim pikinini meri bilong em long Jarha, wokboi bilong em, bilong maritim. Na em i karim Atai long em.',
        36: 'Na Atai i kamapim Netan, na Netan i kamapim Sabat,',
        37: 'Na Sabat i kamapim Eflal, na Eflal i kamapim Obet,',
        38: 'Na Obet i kamapim Jehu, na Jehu i kamapim Asaraia,',
        39: 'Na Asaraia i kamapim Heles, na Heles i kamapim Eleasa,',
        40: 'Na Eleasa i kamapim Sisamai, na Sisamai i kamapim Salum,',
        41: 'Na Salum i kamapim Jekamaia, na Jekamaia i kamapim Elisama.',
        42: 'Nau ol pikinini man bilong Kelep, brata bilong Jeramel, em, Mesa, namba wan pikinini bilong em, husat i papa bilong Sif, na ol pikinini man bilong Maresa, papa bilong Hibron.',
        43: 'Na ol pikinini man bilong Hibron, Kora, na Tapua, na Rekem, na Sema.',
        44: 'Na Sema i kamapim Raham, papa bilong Jorkoam. Na Rekem i kamapim Samai.',
        45: 'Na pikinini man bilong Samai em i Meon. Na Meon em i papa bilong Bet-sur.',
        46: 'Na Ifa, namba tu lain meri bilong Kelep, i karim Haran, na Mosa, na Gases. Na Haran i kamapim Gases.',
        47: 'Na ol pikinini man bilong Jadai, Regem, na Jotam, na Gesan, na Pelet, na Ifa, na Seaf.',
        48: 'Meaka, namba tu lain meri bilong Kelep, i karim Seber, na Tirhana.',
        49: 'Em i karim tu Seaf, papa bilong Matmana, Seva, papa bilong Makbena, na papa bilong Gibea. Na pikinini meri bilong Kelep em i Aksa.',
        50: 'Ol dispela em i ol pikinini man bilong Kelep, pikinini man bilong Hur, namba wan pikinini bilong Efrata, Sobal, papa bilong Kiriat-jerim,',
        51: 'Salma, papa bilong Betlehem, Harep, papa bilong Bet-gader.',
        52: 'Na Sobal, papa bilong Kiriat-jerim i gat ol pikinini man, Haroe, na hap bilong ol lain Manahet.',
        53: 'Na ol famili bilong Kiriat-jerim, ol lain Itra, na ol lain Put, na ol lain Suma, na ol lain Misra. Bilong ol ol lain Sareat, na ol lain Estaul, i kam.',
        54: 'Ol pikinini man bilong Salma, Betlehem, na ol lain Netofa, Atarot, hauslain bilong Joap, na hap bilong ol lain Manahet, ol lain Sora.',
        55: 'Na ol famili bilong ol man bilong rait husat i stap long Jabes, ol lain Tira, ol lain Simeat, na ol lain Sukot. Ol dispela em i ol lain Ken husat i kam long Hemat, papa bilong hauslain bilong Rekap.',
    },
    3: {
        1: '¶ Nau ol dispela em i ol pikinini man bilong Devit, husat ol meri i karim long em long Hibron. Namba wan pikinini em Amnon, long meri Jesril Ahinoam. Namba tu em Danyel, long meri Karmel Abigel.',
        2: 'Namba tri, em Apsalam, pikinini man bilong Meaka, pikinini meri bilong Talmai, king bilong Geser. Namba foa, em Adonaisa, pikinini man bilong Hagit.',
        3: 'Namba faiv, em Sefataia long Abital. Namba sikis, em Itream long meri bilong em Ekla.',
        4: 'Dispela sikispela ol meri i karim long em long Hibron. Na long dispela hap em i bosim kingdom sevenpela yia na sikispela mun. Na long Jerusalem em i bosim kingdom 33 yia.',
        5: 'Na ol dispela ol meri i karim long em long Jerusalem, Simea, na Sobap, na Netan, na Solomon, fopela, long Bat-sua, pikinini meri bilong Amiel.',
        6: 'Ipar tu, na Elisama, na Elifelet,',
        7: 'Na Noga, na Nefek, na Jafia,',
        8: 'Na Elisama, na Eliada, na Elifelet, nainpela.',
        9: 'Ol dispela em olgeta pikinini man bilong Devit, dispela i no kaunim ol pikinini man bilong ol namba tu lain meri, na Temar, susa bilong ol.',
        10: '¶ Na pikinini man bilong Solomon em i Reaboam, pikinini man bilong em Abia, pikinini man bilong em Esa, pikinini man bilong em Jehosafat,',
        11: 'Pikinini man bilong em Joram, pikinini man bilong em Ehasaia, pikinini man bilong em Joas,',
        12: 'Pikinini man bilong em Amasaia, pikinini man bilong em Asaraia, pikinini man bilong em Jotam,',
        13: 'Pikinini man bilong em Ehas, pikinini man bilong em Hesekaia, pikinini man bilong em Manasa,',
        14: 'Pikinini man bilong em Amon, pikinini man bilong em Josaia.',
        15: 'Na ol pikinini man bilong Josaia em, namba wan pikinini Johanan, namba tu Jehoiakim, namba tri Sedekaia, namba foa Salum.',
        16: 'Na ol pikinini man bilong Jehoiakim, pikinini man bilong em Jekonaia, pikinini man bilong em Sedekaia.',
        17: 'Na ol pikinini man bilong Jekonaia, Asir, pikinini man bilong em Salatiel,',
        18: 'Malkiram tu, na Pedea, na Senasar, Jekamaia, Hosama, na Nedabaia.',
        19: 'Na ol pikinini man bilong Pedea em, Serubabel, na Simei. Na ol pikinini man bilong Serubabel, Mesulam, na Hananaia, na Selomit, susa bilong ol.',
        20: 'Na Hasuba, na Ohel, na Berikaia, na Hasadaia, Jusap-heset, faipela.',
        21: 'Na ol pikinini man bilong Hananaia, Pelataia, na Jesea. Ol pikinini man bilong Refea, ol pikinini man bilong Arnan, ol pikinini man bilong Obadaia, ol pikinini man bilong Sekanaia.',
        22: 'Na ol pikinini man bilong Sekanaia, Semea. Na ol pikinini man bilong Semea, Hatus, na Ikeal, na Baraia, na Nearaia, na Safat, sikispela.',
        23: 'Na ol pikinini man bilong Nearaia, Elioenai, na Hesekaia, na Asrikam, tripela.',
        24: 'Na ol pikinini man bilong Elioenai em, Hodea, na Eliasip, na Pelea, na Akup, na Johanan, na Dalea, na Anani, sevenpela.',
    },
    4: {
        1: '¶ Ol pikinini man bilong Juda, Fares, Hesron, na Karmi, na Hur, na Sobal.',
        2: 'Na Reea, pikinini man bilong Sobal, i kamapim Jahat. Na Jahat i kamapim Ahumai, na Lahat. Ol dispela em i ol famili bilong ol lain Sora.',
        3: 'Na ol dispela em i bilong papa bilong Etam, Jesril, na Isma, na Itbas. Na nem bilong susa bilong ol em Haselelponi,',
        4: 'Na Penyuel, papa bilong Gedor, na Eser, papa bilong Husa. Ol dispela em ol pikinini man bilong Hur, namba wan pikinini bilong Efrata, papa bilong Betlehem.',
        5: 'Na Asur, papa bilong Tekoa, i gat tupela meri, Hela na Neara.',
        6: 'Na Neara i karim Ahusam long em, na Hefer, na Temeni, na Heahastari. Ol dispela em ol pikinini man bilong Neara.',
        7: 'Na ol pikinini man bilong Hela em, Seret, na Jesoar, na Etnan.',
        8: 'Na Kos i kamapim Anup, na Sobeba, na ol famili bilong Ahahel, pikinini man bilong Harum.',
        9: 'Na Jebes i gat ona moa long ol brata bilong em. Na mama bilong em i kolim nem bilong em Jebes, i spik, Bilong wanem, mi karim em wantaim bel hevi.',
        10: 'Na Jebes i singaut long God bilong Isrel, i spik, O sapos Yu gat laik long blesim mi tru, na mekim hap arere bilong mi i go traipela, na long han bilong Yu i ken stap wantaim mi, na long Yu ken pasim mi long ol samting nogut, inap long em i no inap givim bel sori long mi! Na God i tok orait long em long dispela samting em i askim.',
        11: '¶ Na Kelup, brata bilong Sua, i kamapim Mehir, husat em i papa bilong Eston.',
        12: 'Na Eston i kamapim Bet-rafa, na Pasea, na Tehina, papa bilong Ir-nahas. Ol dispela em ol man bilong Reka.',
        13: 'Na ol pikinini man bilong Kenas, Otniel, na Serea. Na ol pikinini man bilong Otniel, Hatat.',
        14: 'Na Meonotai i kamapim Ofra. Na Serea i kamapim Joap, papa bilong ples daun bilong Karasim. Long wanem, ol i ol wokman i gat gutpela save.',
        15: 'Na ol pikinini man bilong Kelep, pikinini man bilong Jefune, Iru, Ila, na Neam. Na ol pikinini man bilong Ila, yes, Kenas.',
        16: 'Na ol pikinini man bilong Jehalelel, Sif, na Sifa, Tiria, na Asarel.',
        17: 'Na ol pikinini man bilong Esra em, Jeter, na Meret, na Efer, na Jalon. Na meri i karim Miriam, na Samai, na Isba, papa bilong Estemoa.',
        18: 'Na meri bilong em Jehudaisa i karim long em Jeret, papa bilong Gedor, na Heber, papa bilong Soko, na Jekutiel, papa bilong Sanoa. Na ol dispela em ol pikinini man bilong Bitaia, pikinini meri bilong Fero, husat Meret i kisim.',
        19: 'Na ol pikinini man bilong meri bilong em Hodaia, susa bilong Naham, papa bilong man Garmi Keila, na man Meaka Estemoa.',
        20: 'Na ol pikinini man bilong Simon em, Amnon, na Rina, Ben-hanan, na Tilon. Na ol pikinini man bilong Isi em, Sohet, na Ben-sohet.',
        21: 'Na ol pikinini man bilong Sela, pikinini man bilong Juda, em, Er, papa bilong Leka, na Leada, papa bilong Maresa, na ol famili bilong hauslain bilong ol husat i wokim laplap i naispela tru, bilong hauslain bilong Asbia,',
        22: 'Na Jokim, na ol man bilong Kosiba, na Joas, na Saraf, husat i gat strong long bosim long Moap, na Jasubi-lehem. Na ol dispela em ol samting bilong bipo tru.',
        23: 'Ol dispela em ol man bilong wokim sospen graun, na ol husat i stap namel long ol samting ol i planim na banis plaua. Ol i stap long dispela hap wantaim king long wok bilong em.',
        24: '¶ Ol pikinini man bilong Simion em, Nemyuel, na Jamin, Jarip, Sera, na Saul,',
        25: 'Pikinini man bilong em Salum, pikinini man bilong em Mipsam, pikinini man bilong em Misma.',
        26: 'Na ol pikinini man bilong Misma, pikinini man bilong em Hamuel, pikinini man bilong em Sakur, pikinini man bilong em Simei.',
        27: 'Na Simei i gat 16 pikinini man na sikispela pikinini meri. Tasol ol brata bilong em i no gat planti pikinini, na tu olgeta famili bilong em i no bin kamap planti moa, wankain olsem ol pikinini bilong Juda.',
        28: 'Na ol i stap long Biar-siba, na Molada, na Hasar-sual,',
        29: 'Na long Bilha, na long Esem, na long Tolat,',
        30: 'Na long Betyuel, na long Horma, na long Siklak,',
        31: 'Na long Bet-makabot, na long Hasar-susim, na long Bet-biri, na long Searaim. Ol dispela em ol biktaun bilong ol i go inap long taim Devit i bosim kingdom.',
        32: 'Na ol vilis bilong ol em, Etam, na Ain, Rimon, na Token, na Asan, faipela biktaun,',
        33: 'Na olgeta vilis bilong ol, dispela i stap raun nabaut long ol dispela biktaun stret, i go inap long Beal. Ol dispela em ol ples bilong ol long stap, na ol lain tumbuna bilong ol.',
        34: 'Na Mesobap, na Jamlek, na Josa, pikinini man bilong Amasaia,',
        35: 'Na Joel, na Jehu, pikinini man bilong Josibaia, pikinini man bilong Serea, pikinini man bilong Asiel,',
        36: 'Na Elioenai, na Jeakoba, na Jesohea, na Asea, na Adiel, na Jesimiel, Benea,',
        37: 'Na Sisa, pikinini man bilong Sifi, pikinini man bilong Alon, pikinini man bilong Jedea, pikinini man bilong Simri, pikinini man bilong Semea.',
        38: 'Ol dispela ol i kolim long ol nem bilong ol em ol hetman bilong ol famili bilong ol. Na hauslain bilong ol tumbuna papa bilong ol i kamap bikpela planti moa.',
        39: 'Na ol i go long ai bilong Gedor, yes, i go inap long hap is bilong dispela ples daun, bilong painim ples gras bilong ol lain sipsip bilong ol.',
        40: 'Na ol i painim pinis ples gras i patpela na gutpela, na dispela hap i gat bikpela brait, na i no gat nois, na bel isi i stap. Long wanem, ol bilong Ham i bin stap long dispela hap bipo.',
        41: 'Na ol dispela ol i raitim long nem bilong ol i kam long ol de bilong Hesekaia, king bilong Juda, na paitim ol haus sel bilong ol, na ol dispela ples bilong man long stap ol i lukim long dispela hap, na bagarapim ol olgeta i go inap long tude, na ol i stap long ol ples bilong ol. Bilong wanem, i gat ol ples gras bilong ol lain sipsip bilong ol.',
        42: 'Na sampela bilong ol, yes, bilong ol pikinini man bilong Simion, 500 man, i go long maunten Sir, taim ol i gat bilong ol kepten bilong ol Pelataia, na Nearaia, na Refea, na Usiel, ol pikinini man bilong Isi.',
        43: 'Na ol i paitim olgeta arapela bilong ol lain Amalek husat i ranawe pinis, na stap long dispela hap inap long tude.',
    },
    5: {
        1: '¶ Nau ol pikinini man bilong Ruben, namba wan pikinini bilong Isrel, (long wanem, em i namba wan pikinini, tasol, bikos em i mekim bet bilong papa bilong em doti, rait bilong namba wan pikinini bilong em God i givim long ol pikinini man bilong Josep, pikinini man bilong Isrel. Na lain tumbuna ol i no kaunim nau i bihainim rait bilong namba wan pikinini.',
        2: 'Long wanem, Juda i winim ol brata bilong em, na long em nambawan hetman i kam. Tasol rait bilong namba wan pikinini em i bilong Josep.)',
        3: 'Ol pikinini man, mi tok, bilong Ruben, namba wan pikinini bilong Isrel, em, Hanok, na Palu, Hesron, na Karmi.',
        4: 'Ol pikinini man bilong Joel, pikinini man bilong em Semea, pikinini man bilong em Gok, pikinini man bilong em Simei,',
        5: 'Pikinini man bilong em Reea, pikinini man bilong em Beal,',
        6: 'Pikinini man bilong em Bera, husat Tilgat-pilneser, king bilong Asiria, i karim i go kalabus. Em i hetman bilong ol lain Ruben.',
        7: 'Na ol brata bilong em, long ol famili bilong ol, taim dispela lain tumbuna bilong ol lain tumbuna bilong ol ol i kaunim, ol i nambawan, Jeiel, na Sekaraia,',
        8: 'Na Bela, pikinini man bilong Asas, pikinini man bilong Sema, pikinini man bilong Joel, husat i stap long Aroa, yes, i go inap long Nibo na Beal-meon.',
        9: 'Na long hap is em i stap i go inap long ai bilong ples i no gat man i stat long wara Yufretis. Bilong wanem, ol bulmakau samting bilong ol i kamap planti moa long hap bilong Gileat',
        10: 'Na long ol de bilong Sol ol i wokim bikpela pait wantaim ol lain Hegar, husat i pundaun long han bilong ol. Na ol i stap long ol haus sel bilong ol namel long olgeta hap is bilong hap bilong Gileat',
        11: 'Na ol pikinini bilong Gat i stap pas klostu long ol, long hap bilong Basan i go inap long Salka,',
        12: 'Na Joel, nambawan, na Safam bihain long em, na Jeanai, na Safat long Basan.',
        13: 'Na ol brata bilong ol bilong hauslain bilong ol tumbuna papa bilong ol em, Maikel, na Mesulam, na Siba, na Jorai, na Jakan, na Sia, na Heber, sevenpela.',
        14: 'Ol dispela em ol pikinini bilong Abihail, pikinini man bilong Huri, pikinini man bilong Jaroa, pikinini man bilong Gileat, pikinini man bilong Maikel, pikinini man bilong Jesisai, pikinini man bilong Jado, pikinini man bilong Bus,',
        15: 'Ahi, pikinini man bilong Apdiel, pikinini man bilong Guni, nambawan bilong hauslain bilong ol tumbuna papa bilong ol.',
        16: 'Na ol i stap long Gileat long Basan, na insait long ol taun bilong en, na insait long olgeta ples arere bilong biktaun bilong Saron, long ol hap arere bilong ol.',
        17: 'Olgeta dispela ol i kaunim long bihainim ol lain tumbuna bilong ol long ol de bilong Jotam, king bilong Juda, na long ol de bilong Jeroboam, king bilong Isrel.',
        18: '¶ Ol pikinini man bilong Ruben, na ol lain Gat, na hap lain bilong Manasa, bilong ol strongpela man bilong pait, ol man husat i inap long karim plang bilong han na bainat, na bilong sutim wantaim banara, na i gat save long bikpela pait, em i 44,760, husat i go ausait long bikpela pait.',
        19: 'Na ol i wokim bikpela pait wantaim ol lain Hegar, wantaim Jetur, na Nefis, na Nodap.',
        20: 'Na ol i kisim helpim long birua long ol, na God i givim ol lain Hegar long han bilong ol, na olgeta husat i stap wantaim ol. Long wanem, ol i singaut long God insait long pait, na Em i harim strongpela askim bilong ol. Bilong wanem, ol i putim bilip bilong ol long Em.',
        21: 'Na ol i tekewe ol bulmakau samting bilong ol, bilong ol kemel, 50,000, na bilong ol sipsip, 250,000, na bilong ol donki, 2,000, na bilong ol dispela man 100,000.',
        22: 'Long wanem, i gat planti i pundaun i dai pinis, bilong wanem, dispela bikpela pait i kam long God. Na ol i stap long ol ples bilong ol inap long taim bilong kalabus.',
        23: 'Na ol pikinini bilong hap lain bilong Manasa i stap long dispela hap. Ol i kamap planti moa i stat long Basan i go inap long Beal-hermon na Senir, na i go inap long maunten Hermon.',
        24: 'Na ol dispela em ol het bilong hauslain bilong ol tumbuna papa bilong ol, yes, Efer, na Isi, na Eliel, na Asriel, na Jeremaia, na Hodavaia, na Jadiel, ol strongpela man tru bilong pait, ol man i gat biknem tru, na ol het bilong hauslain bilong ol tumbuna papa bilong ol.',
        25: 'Na ol i kalapim lo i birua long God bilong ol tumbuna papa bilong ol, na go pamuk nabaut i bihainim ol god bilong ol manmeri bilong dispela hap, husat God i bagarapim olgeta long ai bilong ol.',
        26: 'Na God bilong Isrel i kirapim spirit bilong Pul, king bilong Asiria, na spirit bilong Tilgat-pilneser, king bilong Asiria, na em i karim ol i go, yes, ol lain Ruben, na ol lain Gat, na hap lain bilong Manasa, na bringim ol i go inap long Hala, na Habor, na Hara, na i go long wara Gosan, inap long tude.',
    },
    6: {
        1: '¶ Ol pikinini man bilong Livai, Gerson, Kohat, na Merari.',
        2: 'Na ol pikinini man bilong Kohat, Amram, Ishar, na Hibron, na Usiel.',
        3: 'Na ol pikinini bilong Amram, Eron, na Moses, na Miriam. Na ol pikinini man tu bilong Eron, Nedap, na Abaihu, Eleasar, na Itamar.',
        4: 'Eleasar i kamapim Finias, Finias i kamapim Abisua,',
        5: 'Na Abisua i kamapim Buki, na Buki i kamapim Usi,',
        6: 'Na Usi i kamapim Serahaia, na Serahaia i kamapim Meraiot,',
        7: 'Meraiot i kamapim Amaraia, na Amaraia i kamapim Ahitup,',
        8: 'Na Ahitup i kamapim Sedok, na Sedok i kamapim Ahimeas,',
        9: 'Na Ahimeas i kamapim Asaraia, na Asaraia i kamapim Johanan,',
        10: 'Na Johanan i kamapim Asaraia, (em i dispela husat i mekim wok bilong pris insait long dispela tempel Solomon i wokim insait long Jerusalem.)',
        11: 'Na Asaraia i kamapim Amaraia, na Amaraia i kamapim Ahitup,',
        12: 'Na Ahitup i kamapim Sedok, na Sedok i kamapim Salum,',
        13: 'Na Salum i kamapim Hilkaia, na Hilkaia i kamapim Asaraia,',
        14: 'Na Asaraia i kamapim Serea, na Serea i kamapim Jehosadak,',
        15: 'Na Jehosadak i go long kalabus, taim BIKPELA i karim i go Juda na Jerusalem long han bilong Nebukatnesar.',
        16: 'Ol pikinini man bilong Livai, Gersom, Kohat, na Merari.',
        17: 'Na ol dispela em ol nem bilong ol pikinini man bilong Gersom, Lipni, na Simei.',
        18: 'Na ol pikinini man bilong Kohat em, Amram, na Ishar, na Hibron, na Usiel.',
        19: 'Ol pikinini man bilong Merari, Mali, na Musi. Na ol dispela em ol famili bilong ol lain Livai bilong bihainim ol tumbuna papa bilong ol.',
        20: 'Bilong Gersom, pikinini man bilong em Lipni, pikinini man bilong em Jahat, pikinini man bilong em Sima,',
        21: 'Pikinini man bilong em Joa, pikinini man bilong em Ido, pikinini man bilong em Sera, pikinini man bilong em Jeaterai.',
        22: 'Ol pikinini man bilong Kohat, pikinini man bilong em Aminadap, pikinini man bilong em Kora, pikinini man bilong em Asir,',
        23: 'Pikinini man bilong em Elkana, na pikinini man bilong em Ebiasap, na pikinini man bilong em Asir,',
        24: 'Pikinini man bilong em Tahat, pikinini man bilong em Uriel, pikinini man bilong em Usaia, na pikinini man bilong em Saul.',
        25: 'Na ol pikinini man bilong Elkana, Amasai, na Ahimot.',
        26: 'Long sait bilong Elkana, ol pikinini man bilong Elkana, pikinini man bilong em Sofai, na pikinini man bilong em Nahat,',
        27: 'Pikinini man bilong em Eliap, pikinini man bilong em Jeroham, pikinini man bilong em Elkana.',
        28: 'Na ol pikinini man bilong Samyuel, namba wan pikinini Vasni, na Abia.',
        29: 'Ol pikinini man bilong Merari, Mali, pikinini man bilong em Lipni, pikinini man bilong em Simei, pikinini man bilong em Usa,',
        30: 'Pikinini man bilong em Simea, pikinini man bilong em Hagaia, pikinini man bilong em Asea.',
        31: '¶ Na ol dispela em i ol husat Devit i putim long bosim wok bilong song insait long haus bilong BIKPELA, bihain long bokis kontrak i gat malolo.',
        32: 'Na ol i wokim wok long ai bilong ples bilong stap bilong haus sel holi bilong bung bilong ol manmeri wantaim pasin bilong singim song, inap long taim Solomon i bin wokim haus bilong BIKPELA long Jerusalem. Na nau ol i mekim wok long wok bilong ol bilong bihainim taim bilong ol.',
        33: 'Na ol dispela em ol husat i mekim wok wantaim ol pikinini bilong ol. Bilong ol pikinini man bilong ol lain Kohat, Heman, wanpela man bilong singim song, pikinini man bilong Joel, pikinini man bilong Semyuel,',
        34: 'Pikinini man bilong Elkana, pikinini man bilong Jeroham, pikinini man bilong Eliel, pikinini man bilong Toa,',
        35: 'Pikinini man bilong Suf, pikinini man bilong Elkana, pikinini man bilong Mahat, pikinini man bilong Amasai,',
        36: 'Pikinini man bilong Elkana, pikinini man bilong Joel, pikinini man bilong Asaraia, pikinini man bilong Sefanaia,',
        37: 'Pikinini man bilong Tahat, pikinini man bilong Asir, pikinini man bilong Ebiasap, pikinini man bilong Kora,',
        38: 'Pikinini man bilong Ishar, pikinini man bilong Kohat, pikinini man bilong Livai, pikinini man bilong Isrel.',
        39: 'Na brata bilong em Esap, husat i sanap long han sut bilong em, yes, Esap, pikinini man bilong Berikaia, pikinini man bilong Simea,',
        40: 'Pikinini man bilong Maikel, pikinini man bilong Beaseaia, pikinini man bilong Malkaia,',
        41: 'Pikinini man bilong Etni, pikinini man bilong Sera, pikinini man bilong Adea,',
        42: 'Pikinini man bilong Etan, pikinini man bilong Sima, pikinini man bilong Simei,',
        43: 'Pikinini man bilong Jahat, pikinini man bilong Gersom, pikinini man bilong Livai.',
        44: 'Na ol brata bilong ol, ol pikinini man bilong Merari, i sanap long han kais, Etan, pikinini man bilong Kisi, pikinini man bilong Apdi, pikinini man bilong Maluk,',
        45: 'Pikinini man bilong Hasabaia, pikinini man bilong Amasaia, pikinini man bilong Hilkaia,',
        46: 'Pikinini man bilong Amsi, pikinini man bilong Bani, pikinini man bilong Samur,',
        47: 'Pikinini man bilong Mali, pikinini man bilong Musi, pikinini man Merari, pikinini man bilong Livai.',
        48: 'Ol brata bilong ol tu, ol lain Livai, ol i makim i go long olgeta kain kain wok bilong haus sel holi bilong haus bilong God.',
        49: 'Tasol Eron na ol pikinini man bilong em i ofaim antap long alta bilong ol ofa i kuk olgeta, na antap long alta bilong insens, na ol i makim ol bilong olgeta wok bilong ples i holi moa olgeta, na bilong wokim wanpela karamapim long mekim i kamap wanbel bilong helpim Isrel, bilong bihainim olgeta samting Moses, wokboi bilong God, i bin tok strong.',
        50: 'Na ol dispela em ol pikinini man bilong Eron, pikinini man bilong em Eleasar, pikinini man bilong em Finias, pikinini man bilong em Abisua,',
        51: 'Pikinini man bilong em Buki, pikinini man bilong em Usi, pikinini man bilong em Serahaia,',
        52: 'Pikinini man bilong em Meraiot, pikinini man bilong em Amaraia, pikinini man bilong em Ahitup,',
        53: 'Pikinini man bilong em Sedok, pikinini man bilong em Ahimeas.',
        54: '¶ Nau ol dispela em ol ples ol i stap long ol haus king bilong ol long olgeta hap arere bilong ol, bilong ol pikinini man bilong Eron, bilong ol famili bilong ol lain Kohat. Long wanem, bilong ol em dispela hap skel.',
        55: 'Na ol i givim ol Hibron long hap bilong Juda, na ol ples arere bilong biktaun bilong en raun nabaut long en.',
        56: 'Tasol ol ples kunai bilong biktaun, na ol vilis bilong en, ol i givim long Kelep, pikinini man bilong Jefune.',
        57: 'Na long ol pikinini man bilong Eron ol i givim ol biktaun bilong Juda, ol i olsem, Hibron, biktaun bilong hait, na Lipna wantaim ol ples arere bilong biktaun bilong en, na Jatir, na Estemoa, wantaim ol ples arere bilong biktaun bilong ol,',
        58: 'Na Hilen wantaim ol ples arere bilong biktaun bilong en, Debir wantaim ol ples arere bilong biktaun bilong en,',
        59: 'Na Asan wantaim ol ples arere bilong biktaun bilong en, na Bet-semes wantaim ol ples arere bilong biktaun bilong en,',
        60: 'Na ausait long lain bilong Benjamin, Geba wantaim ol ples arere bilong biktaun bilong en, na Alemet wantaim ol ples arere bilong biktaun bilong en, na Anatot wantaim ol ples arere bilong biktaun bilong en. Olgeta biktaun bilong ol long olgeta hap bilong ol famili bilong ol em i 13 biktaun.',
        61: 'Na long ol pikinini man bilong Kohat, husat i stap yet bilong famili bilong dispela lain, ol i givim ol biktaun ausait long dispela hap lain, ol i olsem, ausait long hap lain bilong Manasa, long satu, tenpela biktaun.',
        62: 'Na long ol pikinini man bilong Gersom i long olgeta hap bilong famili bilong ol ausait long lain bilong Isakar, na ausait long lain bilong Aser, na ausait long lain bilong Naptalai, na ausait long lain bilong Manasa long Basan, 13 biktaun.',
        63: 'Ol i givim i go long ol pikinini man bilong Merari long satu, long olgeta hap bilong famili bilong ol, ausait long lain bilong Ruben, na ausait long lain bilong Gat, na ausait long lain bilong Sebyulan, 12 biktaun.',
        64: 'Na ol pikinini bilong Isrel i givim ol lain Livai ol dispela biktaun wantaim ol ples arere bilong biktaun bilong ol.',
        65: 'Na ol i givim long satu ausait long lain bilong ol pikinini bilong Juda, na ausait long lain bilong ol pikinini bilong Simion, na ausait long lain bilong ol pikinini bilong Benjamin, ol dispela biktaun, dispela ol i kolim long ol nem bilong ol.',
        66: 'Na hap lain i stap yet bilong ol famili bilong ol pikinini man bilong Kohat i gat ol biktaun bilong ol hap arere bilong ol ausait long lain bilong Ifraim.',
        67: 'Na ol i givim i go long ol, bilong ol biktaun bilong hait, Sekem long maunten Ifraim wantaim ol ples arere bilong biktaun bilong en. Ol i givim tu Geser wantaim ol ples arere bilong biktaun bilong en,',
        68: 'Na Jokmeam wantaim ol ples arere bilong biktaun bilong en, na Bet-horon wantaim ol ples arere bilong biktaun bilong en,',
        69: 'Na Aisalon wantaim ol ples arere bilong biktaun bilong en, na Gat-rimon wantaim ol ples arere bilong biktaun bilong en.',
        70: 'Na ausait long hap lain bilong Manasa, Aner wantaim ol ples arere bilong biktaun bilong en, na Bileam wantaim ol ples arere bilong biktaun bilong en, bilong famili bilong hap lain i stap yet bilong ol pikinini man bilong Kohat.',
        71: 'Long ol pikinini man bilong Gersom ol i givim ausait long famili bilong hap lain bilong Manasa, Golan long Basan wantaim ol ples arere bilong biktaun bilong en, na Astarot wantaim ol ples arere bilong biktaun bilong en.',
        72: 'Na ausait long lain bilong Isakar, Kedes wantaim ol ples arere bilong biktaun bilong en, Daberat wantaim ol ples arere bilong biktaun bilong en,',
        73: 'Na Ramot wantaim ol ples arere bilong biktaun bilong en, na Anem wantaim ol ples arere bilong biktaun bilong en.',
        74: 'Na ausait long lain bilong Aser, Masal wantaim ol ples arere bilong biktaun bilong en, na Apdon wantaim ol ples arere bilong biktaun bilong en,',
        75: 'Na Hukok wantaim ol ples arere bilong biktaun bilong en, na Rehop wantaim ol ples arere bilong biktaun bilong en.',
        76: 'Na ausait long lain bilong Naptalai, Kedes long Galili wantaim ol ples arere bilong biktaun bilong en, na Hamon wantaim ol ples arere bilong biktaun bilong en, na Kiriatim wantaim ol ples arere bilong biktaun bilong en.',
        77: 'Ol i givim i go long olgeta arapela bilong ol pikinini bilong Merari ausait long lain bilong Sebyulan, Rimon wantaim ol ples arere bilong biktaun bilong en, Tabor wantaim ol ples arere bilong biktaun bilong en.',
        78: 'Na long hapsait bilong Jordan klostu long Jeriko, long hap is sait bilong Jordan, ol i givim ol ausait long lain bilong Ruben, Beser long ples i no gat man wantaim ol ples arere bilong biktaun bilong en, na Jasa wantaim ol ples arere bilong biktaun bilong en,',
        79: 'Kedemot tu wantaim ol ples arere bilong biktaun bilong en, na Mefeat wantaim ol ples arere bilong biktaun bilong en.',
        80: 'Na ausait long lain bilong Gat, Ramot long Gileat wantaim ol ples arere bilong biktaun bilong en, na Mahanaim wantaim ol ples arere bilong biktaun bilong en,',
        81: 'Na Hesbon wantaim ol ples arere bilong biktaun bilong en, na Jaser wantaim ol ples arere bilong biktaun bilong en.',
    },
    7: {
        1: '¶ Nau ol pikinini man bilong Isakar em, Tola, na Pua, Jasup, na Simron, fopela.',
        2: 'Na ol pikinini man bilong Tola, Usi, na Refea, na Jeriel, na Jamai, na Jipsam, na Semyuel, ol het bilong hauslain bilong ol tumbuna papa bilong ol, em i olsem, bilong Tola. Ol i ol strongpela man bilong pait i gat strong long ol lain tumbuna bilong ol, husat namba bilong ol long ol de bilong Devit em 22,600.',
        3: 'Na ol pikinini man bilong Usi, Israhaia. Na ol pikinini man bilong Israhaia, Maikel, na Obadaia, na Joel, Isaia, faipela. Olgeta bilong ol em ol nambawan man.',
        4: 'Na wantaim ol, long ol lain tumbuna bilong ol, i bihainim hauslain bilong ol tumbuna papa bilong ol, em i ol liklik lain ami bilong ol soldia bilong bikpela pait, 36,000 man. Long wanem, ol i gat planti meri na ol pikinini man.',
        5: 'Na ol brata bilong ol namel long olgeta famili bilong Isakar em ol strongpela man bilong pait i gat strong, ol i kaunim insait long olgeta long bihainim ol lain tumbuna bilong ol 87,000.',
        6: 'Ol pikinini man bilong Benjamin, Bela, na Beker, na Jediel, tripela.',
        7: 'Na ol pikinini man bilong Bela, Esbon, na Usi, na Usiel, na Jerimot, na Iri, faipela, ol het bilong hauslain bilong ol tumbuna papa bilong ol, ol strongpela man tru bilong pait. Na ol i kaunim long bihainim ol lain tumbuna bilong ol 22,034.',
        8: 'Na ol pikinini man bilong Beker, Semaira, na Joas, na Eliesar, na Elioenai, na Omri, na Jerimot, na Abaia, na Anatot, na Alamet. Olgeta dispela em ol pikinini man bilong Beker.',
        9: 'Na namba bilong ol, i bihainim lain tumbuna bilong ol long ol lain tumbuna bilong ol, ol het bilong hauslain bilong ol tumbuna papa bilong ol, ol strongpela man tru bilong pait, em 22,200.',
        10: 'Ol pikinini man tu bilong Jediel, Bilhan. Na ol pikinini man bilong Bilhan, Jeus, na Benjamin, na Ihut, na Keneana, na Setan, na Tarsis, na Ahisahar.',
        11: 'Ol dispela, ol pikinini man bilong Jediel, long ol het bilong ol tumbuna papa bilong ol, ol strongpela man tru bilong pait, em 17,200 ol soldia, fit long go ausait long bikpela pait na pait.',
        12: 'Supim tu, na Hupim, ol pikinini bilong Ir, na Husim, ol pikinini man bilong Aher.',
        13: 'Ol pikinini man bilong Naptalai, Jasiel, na Guni, na Jeser, na Salum, ol pikinini man bilong Bilha.',
        14: 'Ol pikinini man bilong Manasa, Asriel, husat em i karim, (tasol namba tu lain meri bilong em, meri Aram, i karim Makir, papa bilong Gileat.',
        15: 'Na Makir i kisim bilong maritim susa bilong Hupim na Supim, husat nem bilong susa bilong en em i Meaka.) Na nem bilong namba tu em i Selofehat. Na Selofehat i gat ol pikinini meri.',
        16: 'Na Meaka, meri bilong Makir, i karim wanpela pikinini man, na em i kolim nem bilong em Peres. Na nem bilong brata bilong en em i Seres. Na ol pikinini man bilong en em i Ulam na Rakem.',
        17: 'Na ol pikinini man bilong Ulam, Bedan. Ol dispela em ol pikinini man bilong Gileat, pikinini man bilong Makir, pikinini man bilong Manasa.',
        18: 'Na susa bilong em Hamoleket i karim Isot, na Abieser, na Mahala.',
        19: 'Na ol pikinini man bilong Semida em, Ahian, na Sekem, na Likhi, na Aniam.',
        20: '¶ Na ol pikinini man bilong Ifraim, Sutela, na pikinini man bilong em Beret, na pikinini man bilong em Tahat, na pikinini man bilong em Elada, na pikinini man bilong em Tahat,',
        21: 'Na pikinini man bilong em Sabat, na pikinini man bilong em Sutela, na Eser, na Eleat, husat ol man bilong Gat, husat ol meri i karim long dispela hap, i kilim i dai, bilong wanem, ol i kam daun long tekewe ol bulmakau samting bilong ol.',
        22: 'Na Ifraim, papa bilong ol, i soim sori planti de, na ol brata bilong em i kam bilong givim bel isi long em.',
        23: 'Na taim em i go insait long meri bilong em, em i kisim bel, na karim wanpela pikinini man, na em i kolim nem bilong em Beraia, bilong wanem, em i go nogut long hauslain bilong em.',
        24: '(Na pikinini meri bilong en em i Sera, husat i wokim Bet-horon daunbilo, na antap, na Usen-sera.)',
        25: 'Na Refa em i pikinini man bilong em, Resep tu, na pikinini man bilong em Tela, na pikinini man bilong em Tahan,',
        26: 'Pikinini man bilong em Leadan, pikinini man bilong em Amihut, pikinini man bilong em Elisama,',
        27: 'Pikinini man bilong em Non, pikinini man bilong em Jehosua.',
        28: 'Na ol samting ol i holimpas na ol ples ol i stap long en, em, Betel na ol taun bilong en, na i go long hap is Nearan, na i go long hap wes Geser, wantaim ol taun bilong ol. Sekem tu na ol taun bilong en, i go inap long Gasa na ol taun bilong en.',
        29: 'Na klostu long ol hap arere bilong ol pikinini bilong Manasa, Bet-sean na ol taun bilong en, Teanak na ol taun bilong en, Megido na ol taun bilong en, Dor na ol taun bilong en. Long ol dispela ol pikinini bilong Josep, pikinini man bilong Isrel, i stap.',
        30: 'Ol pikinini man bilong Aser, Imna, na Isua, na Isuai, na Beraia, na Sera, susa bilong ol.',
        31: 'Na ol pikinini man bilong Beraia, Heber, na Malkiel, husat i papa bilong Birsavit.',
        32: 'Na Heber i kamapim Jaflet, na Somer, na Hotam, na Sua, susa bilong ol.',
        33: 'Na ol pikinini man bilong Jaflet, Pasak, na Bimhal, na Asvat. Ol dispela em ol pikinini bilong Jaflet.',
        34: 'Na ol pikinini man bilong Samur, Ahi, na Roga, Jehuba, na Aram.',
        35: 'Na ol pikinini man bilong brata bilong em Helem, Sofa, na Imna, na Seles, na Amal.',
        36: 'Na ol pikinini man bilong Sofa, Sua, na Harnefer, na Sual, na Beri, na Imra,',
        37: 'Beser, na Hot, na Sama, na Silsa, na Itran, na Bera.',
        38: 'Na ol pikinini man bilong Jeter, Jefune, na Pispa, na Ara.',
        39: 'Na ol pikinini man bilong Ula, Ara, na Haniel, na Resia.',
        40: 'Olgeta dispela em ol pikinini bilong Aser, ol het bilong hauslain bilong ol tumbuna papa bilong ol, ol nambawan na ol strongpela man tru bilong pait, nambawan bilong ol hetman. Na namba bilong ol namel long olgeta hap bilong lain tumbuna bilong ol husat i fit long bikpela pait na pait em 26,000 man.',
    },
    8: {
        1: '¶ Nau Benjamin i kamapim Bela, namba wan pikinini bilong em, Asbel namba tu, na Ahara namba tri,',
        2: 'Noha namba foa, na Rafa namba faiv.',
        3: 'Na ol pikinini man bilong Bela em, Adar, na Gera, na Abihut,',
        4: 'Na Abisua, na Neaman, na Ahoa,',
        5: 'Na Gera, na Sefufan, na Huram.',
        6: 'Na ol dispela em ol pikinini man bilong Ihut, ol dispela em ol het bilong ol tumbuna papa bilong ol husat i stap long Geba, na ol i rausim ol i go long Manahat.',
        7: 'Na Neaman, na Ahaia, na Gera, em i rausim ol, na kamapim Usa, na Ahihut.',
        8: 'Na Saharaim i kamapim ol pikinini long kantri bilong Moap, bihain long em i bin salim ol i go. Husim na Beara em ol meri bilong em.',
        9: 'Na em i kamapim bilong Hodes, meri bilong em, Jobap, na Sibia, na Mesa, na Malkam,',
        10: 'Na Jeus, na Sakia, na Mirma. Ol dispela em ol pikinini man bilong em, ol het bilong ol tumbuna papa bilong ol.',
        11: 'Na bilong Husim em i kamapim Abitup, na Elpeal.',
        12: 'Ol pikinini man bilong Elpeal, Eber, na Misam, na Samet, husat i wokim Ono, na Lot, wantaim ol taun bilong en,',
        13: 'Beraia tu, na Sema, husat em ol het bilong ol tumbuna papa bilong ol bilong ol husat i stap long Aisalon, husat i ranim i go ol lain i stap long Gat,',
        14: 'Na Ahio, Sasak, na Jeremot,',
        15: 'Na Sebadaia, na Arat, na Eder,',
        16: 'Na Maikel, na Ispa, na Joha, ol pikinini man bilong Beraia,',
        17: 'Na Sebadaia, na Mesulam, na Heseki, na Heber,',
        18: 'Ismerai tu, na Jeslaia, na Jobap, ol pikinini man bilong Elpeal,',
        19: 'Na Jakim, na Sikri, na Sapdi,',
        20: 'Na Elienai, na Siltai, na Eliel,',
        21: 'Na Adea, na Berea, na Simrat, ol pikinini man bilong Simhi,',
        22: 'Na Ispan, na Heber, na Eliel,',
        23: 'Na Apdon, na Sikri, na Hanan,',
        24: 'Na Hananaia, na Ilam, na Antotisa,',
        25: 'Na Ifedeaia, na Penyuel, ol pikinini man bilong Sasak,',
        26: 'Na Samserai, na Seharaia, na Atalaia,',
        27: 'Na Jeresaia, na Elaia, na Sikri, ol pikinini man bilong Jeroham.',
        28: 'Ol dispela em ol het bilong ol tumbuna papa, long ol lain tumbuna bilong ol, ol nambawan man. Ol dispela i stap long Jerusalem.',
        29: 'Na long Gibion papa bilong Gibion i stap, husat nem bilong meri bilong en em Meaka,',
        30: 'Na namba wan pikinini man bilong en em i Apdon, na Sur, na Kis, na Beal, na Nedap,',
        31: 'Na Gedor, na Ahio, na Saker.',
        32: 'Na Miklot i kamapim Simea. Na ol dispela tu i stap wantaim ol brata bilong ol long Jerusalem, pas klostu long ol.',
        33: '¶ Na Ner i kamapim Kis, na Kis i kamapim Sol, na Sol i kamapim Jonatan, na Malkisua, na Abinadap, na Es-beal.',
        34: 'Na pikinini man bilong Jonatan em Meribeal. Na Meribeal i kamapim Maika.',
        35: 'Na ol pikinini man bilong Maika em, Piton, na Melek, na Tarea, na Ehas.',
        36: 'Na Ehas i kamapim Jehoada. Na Jehoada i kamapim Alemet, na Asmavet, na Simri. Na Simri i kamapim Mosa,',
        37: 'Na Mosa i kamapim Binea. Pikinini man bilong en em i Rafa, pikinini man bilong em Eleasa, pikinini man bilong em Asel.',
        38: 'Na Asel i gat sikispela pikinini man, husat ol nem bilong ol em i ol dispela, Asrikam, Bokeru, na Ismel, na Searaia, na Obadaia, na Hanan. Olgeta dispela em ol pikinini man bilong Asel.',
        39: 'Na ol pikinini man bilong Esek, brata bilong em, em, Ulam, namba wan pikinini bilong em, Jehus namba tu, na Elifelet namba tri.',
        40: 'Na ol pikinini man bilong Ulam em ol strongpela man tru bilong pait, ol man bilong sutim banara, na ol i gat planti pikinini man, na ol pikinini man bilong ol pikinini man, 150. Olgeta dispela em ol pikinini man bilong Benjamin.',
    },
    9: {
        1: '¶ Olsem na olgeta Isrel ol i kaunim long ol lain tumbuna bilong ol. Na, lukim, ol i raitim nem bilong ol long buk bilong ol king bilong Isrel na Juda, husat ol i karim ol i go long Babilon, bilong ol pasin bilong ol bilong kalapim lo.',
        2: 'Nau ol namba wan man husat i stap insait long ol holimpas bilong ol insait long ol biktaun bilong ol, em, ol lain Isrel, ol pris, ol lain Livai, na ol wokboi bilong tempel.',
        3: 'Na insait long Jerusalem i stap bilong ol pikinini bilong Juda, na bilong ol pikinini bilong Benjamin, na bilong ol pikinini bilong Ifraim, na Manasa,',
        4: 'Utai, pikinini man bilong Amihut, pikinini man bilong Omri, pikinini man bilong Imri, pikinini man bilong Bani, bilong ol pikinini bilong Fares, pikinini man bilong Juda.',
        5: 'Na bilong ol lain Sailo, Asea, namba wan pikinini, na ol pikinini man bilong em.',
        6: 'Na bilong ol pikinini man bilong Sera, Jeuel, na ol brata bilong ol, 690.',
        7: 'Na bilong ol pikinini man bilong Benjamin, Salu, pikinini man bilong Mesulam, pikinini man bilong Hodavaia, pikinini man bilong Hasenua,',
        8: 'Na Ibneaia, pikinini man bilong Jeroham, na Ila, pikinini man bilong Usi, pikinini man bilong Mikri, na Mesulam, pikinini man bilong Sefataia, pikinini man bilong Reuel, pikinini man bilong Ipnaisa.',
        9: 'Na ol brata bilong ol, bilong bihainim ol lain tumbuna bilong ol, 956. Olgeta dispela man em i nambawan bilong ol tumbuna papa bilong ol long hauslain bilong ol tumbuna papa bilong ol.',
        10: 'Na bilong ol pris, Jedea, na Jehoiarip, na Jakin,',
        11: 'Na Asaraia, pikinini man bilong Hilkaia, pikinini man bilong Mesulam, pikinini man bilong Sedok, pikinini man bilong Meraiot, pikinini man bilong Ahitup, hetman bilong haus bilong God.',
        12: 'Na Adea, pikinini man bilong Jeroham, pikinini man bilong Pasur, pikinini man bilong Malkaisa, na Measiai, pikinini man bilong Adiel, pikinini man bilong Jasera, pikinini man bilong Mesulam, pikinini man bilong Mesilemit, pikinini man bilong Imer.',
        13: 'Na ol brata bilong ol, ol het bilong hauslain bilong ol tumbuna papa bilong ol, 1,760, ol man i inap tru long wok bilong wok bilong haus bilong God.',
        14: '¶ Na bilong ol lain Livai, Semea, pikinini man bilong Hasup, pikinini man bilong Asrikam, pikinini man bilong Hasabaia, bilong ol pikinini man bilong Merari,',
        15: 'Na Bakbakar, Heres, na Galal, na Matanaia, pikinini man bilong Maika, pikinini man bilong Sikri, pikinini man bilong Esap,',
        16: 'Na Obadaia, pikinini man bilong Semea, pikinini man bilong Galal, pikinini man bilong Jedutun, na Berikaia, pikinini man bilong Esa, pikinini man bilong Elkana, husat i stap long ol vilis bilong ol lain Netofa.',
        17: 'Na ol wasman bilong dua em, Salum, na Akup, na Talmon, na Ahiman, na ol brata bilong ol. Salum em i nambawan.',
        18: 'Ol i husat inap long nau i mekim wok insait long dua bilong banis bilong king i go long hap is. Ol i stap ol wasman bilong dua long ol liklik lain bilong ol pikinini bilong Livai.',
        19: 'Na Salum, pikinini man bilong Kore, pikinini man bilong Ebiasap, pikinini man bilong Kora, na ol brata bilong em, bilong hauslain bilong tumbuna papa bilong em, ol lain Kora, ol i bosim wok bilong dispela wok, ol wasman bilong ol dua bilong banis bilong haus sel holi. Na ol tumbuna papa bilong ol, husat i bosim ami bilong BIKPELA, em ol wasman bilong dua.',
        20: 'Na Finias, pikinini man bilong Eleasar, em i hetman i bosim ol long taim bipo, na BIKPELA i stap wantaim em.',
        21: 'Na Sekaraia, pikinini man bilong Meselemaia, em i wasman bilong dua bilong haus sel holi bilong bung bilong ol manmeri.',
        22: 'Olgeta dispela husat ol i makim bilong stap ol wasman bilong ol dua bilong banis em 212. Ol dispela ol i kaunim long lain tumbuna bilong ol long ol vilis bilong ol, husat Devit na sia Samyuel i bin makim insait long wok ol i makim bilong ol.',
        23: 'Olsem na ol na ol pikinini bilong ol i gat wok bilong bosim ol dua bilong banis bilong haus bilong BIKPELA, em i olsem, haus bilong haus sel holi, long ol rum.',
        24: 'Long fopela namba foa hap em ol wasman bilong dua, i go long hap is, hap wes, hap not, na hap saut.',
        25: 'Na ol brata bilong ol, husat i stap long ol vilis, ol i bilong kam bihain long sevenpela de, long ol wan wan taim, wantaim ol.',
        26: 'Long wanem, ol dispela lain Livai, dispela fopela nambawan wasman bilong dua, i stap insait long wok ol i makim bilong ol, na ol i bosim ol rum na ol bakstua mani bilong haus bilong God.',
        27: 'Na ol i slip raun nabaut long haus bilong God, bilong wanem, wok i stap antap long ol, na wok bilong opim dispela olgeta wan wan moning em i samting bilong ol.',
        28: 'Na sampela bilong ol i gat wok bilong ol sospen samting bilong wokim wok, inap long ol i mas bringim ol insait na ausait taim ol i kaunim.',
        29: 'Sampela bilong ol tu ol i makim bilong bosim ol sospen samting, na olgeta samting bilong rum holi, na naispela plaua, na wain, na wel, na frankinsens, na ol spais.',
        30: 'Na sampela bilong ol pikinini man bilong ol pris i wokim ol wel i gat marasin long ol spais.',
        31: 'Na Matitaia, wanpela bilong ol lain Livai, husat i namba wan pikinini bilong man Kora Salum, i gat wok ol i makim long bosim ol dispela samting ol i wokim insait long ol sospen.',
        32: 'Na arapela bilong ol brata bilong ol, bilong ol pikinini man bilong Kohat, i bosim bret bilong soim, bilong redim dispela olgeta wan wan sabat.',
        33: 'Na ol dispela em ol man bilong singim song, nambawan bilong ol tumbuna papa bilong ol bilong ol lain Livai, husat taim ol i stap yet insait long ol rum, ol i stap fri. Long wanem, ol i wokim wok long dispela wok san na nait.',
        34: 'Ol dispela nambawan bilong ol tumbuna papa bilong ol lain Livai i nambawan long olgeta hap bilong lain tumbuna bilong ol. Ol dispela i stap long Jerusalem.',
        35: '¶ Na long Gibion papa bilong Gibion i stap, Jehiel, husat nem bilong meri bilong en em Meaka.',
        36: 'Na namba wan pikinini man bilong en em i Apdon, nau Sur, na Kis, na Beal, na Ner, na Nedap,',
        37: 'Na Gedor, na Ahio, na Sekaraia, na Miklot.',
        38: 'Na Miklot i kamapim Simeam. Na ol tu i stap wantaim ol brata bilong ol long Jerusalem, pas klostu long ol brata bilong ol.',
        39: 'Na Ner i kamapim Kis. Na Kis i kamapim Sol. Na Sol i kamapim Jonatan, na Malkisua, na Abinadap, na Es-beal.',
        40: 'Na pikinini man bilong Jonatan em Meribeal. Na Meribal i kamapim Maika.',
        41: 'Na ol pikinini man bilong Maika em, Piton, na Melek, na Tarea, na Ehas.',
        42: 'Na Ehas i kamapim Jara. Na Jara i kamapim Alemet, na Asmavet, na Simri. Na Simri i kamapim Mosa.',
        43: 'Na Mosa i kamapim Binea, na pikinini man bilong em Refea, pikinini man bilong em Eleasa, pikinini man bilong em Asel.',
        44: 'Na Asel i gat sikispela pikinini man, husat ol nem bilong ol em ol dispela, Asrikam, Bokeru, na Ismel, na Searaia, na Obadaia, na Hanan. Ol dispela em ol pikinini man bilong Asel.',
    },
    10: {
        1: '¶ Nau ol Filistin i pait birua long Isrel. Na ol man bilong Isrel i ranawe long ai bilong ol Filistin, na pundaun i dai pinis long maunten Gilboa.',
        2: 'Na ol Filistin i bihainim strong Sol, na i bihainim ol pikinini man bilong em. Na ol Filistin i kilim i dai Jonatan, na Abinadap, na Malkisua, ol pikinini man bilong Sol.',
        3: 'Na pait i go strong tru i birua long Sol, na ol man bilong sutim banara i sutim em, na em i kisim bagarap long ol man bilong sutim banara.',
        4: 'Nau Sol i tokim man bilong karim klos pait bilong em, Kamautim bainat bilong yu, na sutim mi namel wantaim dispela. Nogut ol dispela lain i no katim skin i kam na bagarapim mi nogut. Tasol man bilong karim klos pait bilong em i no laik. Long wanem, em i pret tru. Olsem na Sol i kisim wanpela bainat, na pundaun antap long en.',
        5: 'Na taim man bilong karim klos pait bilong em i luksave long Sol i dai pinis, em i pundaun wankain olsem antap long bainat, na dai pinis.',
        6: 'Olsem na Sol i dai pinis, na tripela pikinini man bilong em, na olgeta hauslain bilong em i dai pinis wantaim.',
        7: 'Na taim olgeta man bilong Isrel husat i stap long ples daun i luksave long ol i ranawe, na long Sol na ol pikinini man bilong em i dai pinis, nau ol i givim baksait long ol biktaun bilong ol, na ranawe. Na ol Filistin i kam na stap insait long ol.',
        8: '¶ Na em i kamap olsem long moning bihain, taim ol Filistin i kam bilong rausim ol samting bilong ol man ol i kilim i dai, long ol i lukim Sol na ol pikinini man bilong em i pundaun long maunten Gilboa.',
        9: 'Na taim ol i bin rausim ol samting bilong em, ol i kisim het bilong em, na klos pait bilong em, na salim tok i go long hap bilong ol Filistin raun nabaut, bilong karim stori i go long ol piksa bilong god giaman bilong ol, na long ol manmeri.',
        10: 'Na ol i putim ol klos pait bilong em insait long haus bilong ol god bilong ol, na pasim het bilong em insait long tempel bilong Degon.',
        11: 'Na taim olgeta Jebes-gileat i harim olgeta samting ol Filistin i bin mekim long Sol,',
        12: 'Ol i kirap, olgeta strongpela man bilong pait, na ol i tekewe bodi bilong Sol, na ol bodi bilong ol pikinini man bilong em, na bringim ol long Jebes, na planim ol bun bilong ol aninit long ok i stap long Jebes, na tambuim kaikai sevenpela de.',
        13: 'Olsem na Sol i dai pinis long ol dispela pasin bilong em bilong kalapim lo em i mekim i birua long BIKPELA, yes, i birua long tok bilong BIKPELA, dispela em i no holimpas, na tu bikos em i askim tok helpim long wanpela husat i gat wanpela spirit klostu, bilong askim long en,',
        14: 'Na em i no askim long BIKPELA. Olsem na Em i kilim em i dai, na tanim kingdom i go long Devit, pikinini man bilong Jesi.',
    },
    11: {
        1: '¶ Nau olgeta Isrel i bungim ol yet wantaim long Devit long Hibron, i spik, Lukim, mipela i stap bun bilong yu na bodi bilong yu.',
        2: 'Na moa tu long taim bipo, yes, taim Sol i king, em i yu husat i bin stiaim Isrel long go ausait na bringim ol insait. Na BIKPELA, God bilong yu, i tokim yu, Yu bai givim kaikai long ol manmeri bilong Mi Isrel, na yu bai stap hetman long bosim ol manmeri bilong Mi Isrel.',
        3: 'Olsem na olgeta lapun hetman bilong Isrel i kam long king long Hibron. Na Devit i wokim wanpela kontrak wantaim ol long Hibron long ai bilong BIKPELA. Na ol i makim Devit king long bosim Isrel, bilong bihainim tok bilong BIKPELA long maus bilong Samyuel.',
        4: 'Na Devit na olgeta Isrel i go long Jerusalem, dispela em Jebus, we ol lain Jebus i stap, ol husat i stap long dispela hap.',
        5: 'Na ol husat i stap long Jebus i tokim Devit, Yu no ken kam long hia. Tasol Devit i kisim haus king bilong Saion, dispela em i biktaun bilong Devit.',
        6: 'Na Devit i tok, Husat man i paitim ol lain Jebus pastaim bai stap nambawan na kepten. Olsem na Joap, pikinini man bilong Seruaia, i go antap pastaim, na em i nambawan.',
        7: 'Na Devit i stap dispela long haus king. Olsem na ol i kolim dispela biktaun bilong Devit.',
        8: 'Na em i wokim dispela biktaun raun nabaut, yes, i stat long Milo raun nabaut. Na Joap i stretim olgeta arapela hap bilong dispela biktaun.',
        9: 'Olsem na Devit i wok long kamap bikpela na bikpela moa. Long wanem, BIKPELA bilong ol ami i stap wantaim em.',
        10: '¶ Ol dispela tu em ol nambawan bilong ol strongpela man husat Devit i gat, husat i strongim ol yet wantaim em insait long kingdom bilong em, na wantaim olgeta Isrel, long mekim em king, bilong bihainim tok bilong BIKPELA long sait bilong Isrel.',
        11: 'Na dispela em i namba bilong ol strongpela man husat Devit i gat, wanpela man Hakmon Jasobeam, nambawan bilong ol kepten. Em i litimapim spia bilong tromoi bilong em i birua long 300 husat em i kilim i dai long wanpela taim.',
        12: 'Na bihain long en em i Eleasar, pikinini man bilong man Ahoa Dodo, husat i wanpela bilong dispela tripela strongpela.',
        13: 'Em i stap wantaim Devit long Pas-damim, na long dispela hap ol Filistin i bung wantaim bilong pait, we i gat wanpela hap graun i pulap wantaim bali. Na ol manmeri i ranawe long ai bilong ol Filistin.',
        14: 'Na ol i putim ol yet insait long namel bilong dispela hap graun, na kisim bek dispela, na kilim i dai ol Filistin. Na BIKPELA i kisim bek ol wantaim wanpela bikpela kisim bek.',
        15: 'Nau tripela bilong dispela 30 kepten i go daun long ston long Devit, i go insait long hul bilong graun Adulam. Na ami bilong ol Filistin i wokim kem long ples daun bilong Refaim.',
        16: 'Na Devit i stap nau insait long dispela ples hait, na lain soldia bilong ol Filistin i stap nau long Betlehem.',
        17: 'Na Devit i gat laik tru, na tok, O sapos wanpela i ken givim mi dring i kam long wara bilong hul wara bilong Betlehem, dispela i stap long dua bilong banis!',
        18: 'Na dispela tripela i brukim i go namel long ami bilong ol Filistin, na pulim wara i kam ausait long hul wara bilong Betlehem, dispela i stap klostu long dua bilong banis, na kisim dispela, na bringim dispela long Devit. Tasol Devit i no laik dring long en, tasol em i kapsaitim dispela i go long BIKPELA,',
        19: 'Na tok, Long mi, i no ken tru long God bilong mi, long mi ken mekim dispela samting. Ating bai mi dringim blut bilong ol dispela man husat i bin putim ol laip bilong ol aninit long bikpela bagarap? Long wanem, wantaim pasin bilong putim ol laip bilong ol aninit long bikpela bagarap ol i bringim dispela. Olsem na em i tok nogat long dringim dispela. Ol dispela samting dispela tripela i strongpela moa i mekim.',
        20: 'Na Abisai, brata bilong Joap, em i nambawan bilong dispela tripela. Long wanem, em i litimapim spia bilong tromoi bilong em i birua long 300 man, em i kilim ol i dai, na em i gat wanpela nem namel long dispela tripela.',
        21: 'Bilong dispela tripela, em i gat ona moa long dispela tupela. Long wanem, em i kepten bilong ol. Tasol em i no kamap long namba wan tripela.',
        22: 'Benea, pikinini man bilong Jehoiada, pikinini man bilong wanpela strongpela man bilong pait bilong Kapsel, husat i bin mekim planti wok. Em i kilim i dai tupela man i olsem laion bilong Moap. Na tu em i go daun na kilim i dai wanpela laion insait long wanpela bikpela hul long wanpela de i gat ais.',
        23: 'Na em i kilim i dai wanpela man Isip, wanpela man i longpela tru, faipela kyubit antap. Na long han bilong man Isip wanpela spia bilong tromoi i stap olsem wanpela bikpela hap diwai bilong man bilong wokim laplap. Na em i go daun long em wantaim wanpela stik bilong pait, na kamautim spia bilong tromoi ausait long han bilong man Isip, na kilim em i dai wantaim spia bilong tromoi bilong em yet.',
        24: 'Ol dispela samting Benea, pikinini man bilong Jehoiada, i mekim, na em i gat dispela nem namel long dispela tripela strongpela.',
        25: 'Lukim, em i gat ona namel long dispela 30, tasol em i no kamap long dispela namba wan tripela. Na Devit i putim em long bosim ol wasman bilong em.',
        26: 'Na tu ol strongpela man bilong pait bilong ol ami em, Asahel, brata bilong Joap, Elhanan, pikinini man bilong Dodo bilong Betlehem,',
        27: 'Man Haror Samot, man Pelon Heles,',
        28: 'Ira, pikinini man bilong man Tekoa Ikes, man Antot Abieser,',
        29: 'Man Husa Sibekai, man Ahoha Ilai,',
        30: 'Man Netofa Maharai, Helet, pikinini man bilong man Netofa Beana,',
        31: 'Itai, pikinini man bilong man Gibea Ribai, husat i bilong ol pikinini bilong Benjamin, man Piraton Benea,',
        32: 'Hurai bilong ol liklik wara Geas, man Arba Abiel,',
        33: 'Man Baharum Asmavet, man Sealbim Eliaba,',
        34: 'Ol pikinini man bilong man Gison Hasem, Jonatan, pikinini man bilong man Harar Sage,',
        35: 'Ahiam, pikinini man bilong man Harar Sakar, Elifal, pikinini man bilong Ur,',
        36: 'Man Mekera Hefer, man Pelon Ahaisa,',
        37: 'Man Karmel Hesro, Nearai, pikinini man bilong Esbai,',
        38: 'Joel, brata bilong Netan, Miphar, pikinini man bilong Hageri,',
        39: 'Man Amon Selek, man Berot Naharai, man bilong karim klos pait bilong Joap, pikinini man bilong Seruaia,',
        40: 'Man Itra Ira, man Itra Garep,',
        41: 'Man Hit Yuraia, Sabat, pikinini man bilong Alai,',
        42: 'Adina, pikinini man bilong man Ruben Sisa, wanpela kepten bilong ol lain Ruben, na 30 man wantaim em,',
        43: 'Hanan, pikinini man bilong Meaka, na man Miten Josafat,',
        44: 'Man Asterat Usia, Sama na Jehiel, ol pikinini man bilong man Aroer Hotan,',
        45: 'Jediel, pikinini man bilong Simri, na brata bilong em man Tisa Joha,',
        46: 'Man Mahava Eliel, na Jeribai, na Josavaia, ol pikinini man bilong Elneam, na man Moap Itma,',
        47: 'Eliel, na Obet, na man Mesoba Jasiel.',
    },
    12: {
        1: '¶ Nau ol dispela em i ol husat i kam long Devit long Siklak, taim em i pasim em yet klostu yet, bilong wanem, bilong tingim Sol, pikinini man bilong Kis. Na ol i stap namel long ol strongpela man, ol man bilong helpim long bikpela pait.',
        2: 'Ol i gat ol banara bilong pait, na ol i inap long yusim han sut na han kais wantaim long tromoi ol ston na sutim ol spia ausait long banara, yes, ol brata bilong Sol bilong lain Benjamin',
        3: 'Nambawan bilong ol em Ahieser, nau Joas, ol pikinini man bilong man Gibia Semea, na Jesiel, na Pelet, ol pikinini man bilong Asmavet, na Beraka, na man Anatot Jehu,',
        4: 'Na man Gibion Ismea, wanpela strongpela man namel long dispela 30, na i bosim dispela 30, na Jeremaia, na Jahasiel, na Johanan, na man Gedera Josabat,',
        5: 'Elusai, na Jerimot, na Bealaia, na Semaraia, na man Harup Sefataia,',
        6: 'Elkana, na Jesaia, na Asarel, na Joeser, na Jasobeam, ol lain Kora,',
        7: 'Na Joela, na Sebadaia, ol pikinini man bilong Jeroham bilong Gedor.',
        8: 'Na bilong ol lain Gat i gat husat i brukim ol yet i go long Devit i go long dispela ples hait long ples i no gat man, ol strongpela man, na ol man bilong bikpela pait i fit bilong pait, husat i inap long holim plang na plang bilong han, husat ol pes bilong ol em i olsem ol pes bilong ol laion, na ol i stap ol man bilong ran hariap olsem ol ro antap long ol maunten.',
        9: 'Eser namba wan, Obadaia namba tu, Eliap namba tri,',
        10: 'Mismana namba foa, Jeremaia namba faiv,',
        11: 'Atai namba sikis, Eliel namba seven,',
        12: 'Johanan namba et, Elsabat namba nain,',
        13: 'Jeremaia namba ten, Makbanai namba eleven.',
        14: 'Ol dispela em i ol pikinini man bilong Gat, ol kepten bilong ami. Wanpela i las bilong ol i bosim wan handret, na bikpela moa bilong ol i bosim wan tausen.',
        15: 'Ol dispela em ol husat i go hapsait long Jordan long namba wan mun, taim dispela i bin kapsaitim olgeta hap arere bilong en. Na ol i mekim olgeta lain bilong ol ples daun long ranawe, i go long hap is, na i go long hap wes wantaim.',
        16: 'Na i gat i kam, bilong ol pikinini bilong Benjamin na Juda, long dispela ples hait i go long Devit.',
        17: 'Na Devit i go ausait bilong bungim ol, na bekim na tokim ol, Sapos yupela i kam wantaim bel isi long mi long helpim mi, bel bilong mi bai pas long yupela. Tasol sapos yupela i kam long putim mi long han bilong ol birua bilong mi, taim yupela i luksave olsem i no gat rong long han bilong mi, God bilong ol tumbuna papa bilong yumi ken lukluk long en na hatim dispela.',
        18: 'Nau spirit i kam antap long Amasai, husat i nambawan bilong ol kepten, na em i tok, Mipela i bilong yu, Devit, na stap long sait bilong yu, yu pikinini man bilong Jesi. Bel isi, bel isi i stap long yu, na bel isi i stap long ol lain bilong helpim yu. Long wanem, God bilong yu i save helpim yu. Nau Devit i kisim ol, na mekim ol i kamap ol kepten bilong liklik lain ami.',
        19: 'Na i gat sampela bilong Manasa i go long Devit, taim em i kam wantaim ol lain Filistin long birua long Sol long pait. Tasol ol i no helpim ol. Long wanem, ol bikman bilong ol lain Filistin, taim ol i kisim tingting, i salim em i go, i spik, Em bai go long bikman bilong em Sol bilong putim ol het bilong yumi aninit long bikpela bagarap.',
        20: 'Taim em i go long Siklak, i gat i go long em bilong Manasa, Atna, na Josabat, na Jediel, na Maikel, na Josabat, na Ilaihu, na Siltai, ol kepten bilong ol tausen husat i bilong Manasa.',
        21: 'Na ol i helpim Devit long birua long liklik lain ami bilong raun. Long wanem, olgeta bilong ol i strongpela man tru bilong pait, na ol kepten insait long ami.',
        22: 'Long wanem, long dispela taim, long olgeta wan wan de, i gat ol man i kam long Devit long helpim em, inap long dispela i stap wanpela bikpela ami, olsem ami bilong God.',
        23: '¶ Na ol dispela em ol namba bilong ol liklik lain ami husat i redi bilong pait long bikpela pait, na i kam long Devit long Hibron, bilong tanim kingdom bilong Sol i go long em, bilong bihainim tok bilong BIKPELA.',
        24: 'Ol pikinini bilong Juda husat i karim ol plang na spia bilong tromoi em 6,800, redi long pait long bikpela pait.',
        25: 'Bilong ol pikinini bilong Simion, ol strongpela man tru bilong pait bilong bikpela pait, 7,100.',
        26: 'Bilong ol pikinini bilong Livai 4,600.',
        27: 'Na Jehoiada em i hetman bilong ol lain Eron, na wantaim em i gat 3,700,',
        28: 'Na Sedok, wanpela yangpela strongpela man tru bilong pait, na bilong hauslain bilong tumbuna papa bilong em 22 kepten.',
        29: 'Na bilong ol pikinini bilong Benjamin, ol kandre bilong Sol, 3,000. Long wanem, i kam inap long nau, bikpela hap moa bilong ol i bin holimpas was bilong hauslain bilong Sol.',
        30: 'Na ol pikinini bilong Ifraim 20,800, ol strongpela man tru bilong pait, husat i gat biknem tru long olgeta hap bilong hauslain bilong ol tumbuna papa bilong ol.',
        31: 'Na bilong hap lain bilong Manasa, 18,000, husat ol i kolim long nem bilong ol, long kam na mekim Devit king.',
        32: 'Na bilong ol pikinini bilong Isakar, husat i ol man husat i gat gutpela save long ol taim, long save long Isrel i mas i mekim wanem, ol het bilong ol em 200. Na olgeta brata bilong ol i stap aninit long tok strong bilong ol.',
        33: 'Bilong Sebyulan, kain man husat i go ausait long pait, husat i saveman tru long bikpela pait, wantaim olgeta samting bilong bikpela pait, 50,000, husat i ken holimpas lain gut. Ol i no gat tupela bel.',
        34: 'Na bilong Naptalai wan tausen kepten, na wantaim ol, wantaim plang na spia bilong tromoi, 37,000.',
        35: 'Na bilong ol lain Dan husat i saveman tru long bikpela pait 28,600.',
        36: 'Na bilong Aser, kain man husat i go ausait long pait, husat i saveman tru long bikpela pait, 40,000.',
        37: 'Na long hapsait bilong Jordan, bilong ol lain Ruben, bilong ol lain Gat, na bilong hap lain bilong Manasa, wantaim olgeta kain kain samting bilong bikpela pait bilong pait, 120,000.',
        38: 'Olgeta dispela ol man bilong bikpela pait, husat i ken holimpas lain gut, i kam wantaim wanpela bel i inap tru long Hibron, long mekim Devit king long bosim olgeta Isrel. Na olgeta arapela tu bilong Isrel i gat wanpela bel bilong mekim Devit king.',
        39: 'Na long dispela hap ol i stap wantaim Devit tripela de, na kaikai na dring. Long wanem, ol brata bilong ol i bin redim bilong ol.',
        40: 'Na moa tu ol husat i stap klostu long ol, yes, i go long Isakar na Sebyulan na Naptalai, i bringim bret antap long ol donki, na antap long ol kemel, na antap long ol miul, na antap long ol bulmakau man, na abus, plaua, ol kek bilong fik, na ol mekpas bilong resen, na wain, na wel, na ol bulmakau man, na sipsip i planti moa yet. Long wanem, i gat amamas tru i stap long Isrel.',
    },
    13: {
        1: '¶ Na Devit i kisim tingting wantaim ol kepten bilong ol tausen na ol handret, na wantaim olgeta wan wan lida.',
        2: 'Na Devit i tokim olgeta bung bilong ol manmeri bilong Isrel, Sapos em i luk olsem em i gutpela long ai bilong yupela, na sapos em i bilong BIKPELA, God bilong yumi, larim yumi salim tok i go ausait i go long ol brata bilong yumi long olgeta hap, husat i stap yet long olgeta hap bilong Isrel, na wantaim ol tu long ol pris na ol lain Livai husat i stap long ol biktaun na ol ples arere bilong biktaun bilong ol, inap long ol i ken bungim ol yet i kam long yumi.',
        3: 'Na larim yumi bringim gen bokis kontrak bilong God bilong yumi i kam long yumi. Long wanem, yumi no askim long en long ol de bilong Sol.',
        4: 'Na olgeta bung bilong ol manmeri i tok long ol bai mekim olsem. Long wanem, dispela samting em i stretpela long ol ai bilong olgeta manmeri.',
        5: 'Olsem na Devit i bungim olgeta Isrel wantaim, i stat long Saihor bilong Isip, yes, i go inap long ai bilong Hemat, long bringim bokis kontrak bilong God i lusim Kiriat-jerim i kam.',
        6: 'Na Devit i go antap, na olgeta Isrel, long Beala, em i olsem, long Kiriat-jerim, dispela i bilong Juda, bilong bringim bokis kontrak bilong God BIKPELA i kam antap long dispela ples, husat i stap namel long tupela serupim, husat nem bilong Em ol i putim antap long en.',
        7: 'Na ol i karim bokis kontrak bilong God long wanpela nupela karis ausait long haus bilong Abinadap. Na Usa na Ahio i ranim karis.',
        8: 'Na Devit na olgeta Isrel i pilai long ai bilong God wantaim olgeta strong bilong ol, na wantaim pasin bilong singim song, na wantaim ol harp, na wantaim ol kain gita, na wantaim ol liklik kundu, na wantaim ol simbol, na wantaim ol biugel.',
        9: '¶ Na taim ol i kam long plua bilong klinim wit bilong Kidon, Usa i putim han bilong em i go ausait long holimpas bokis kontrak. Long wanem, ol bulmakau man i sutim lek.',
        10: 'Na belhat bilong BIKPELA i kirap na birua long Usa, na Em i paitim em, bilong wanem, em i putim han bilong em long bokis kontrak. Na em i dai pinis long dispela hap long ai bilong God.',
        11: 'Na bel bilong Devit i no amamas, bilong wanem, BIKPELA i bin wokim wanpela bruk antap long Usa. Olsem na nem bilong dispela ples ol i kolim Peres-usa inap long tude.',
        12: 'Na Devit em i pret long God long dispela de, i spik, Bai mi bringim bokis kontrak bilong God i kam long mi long ples olsem wanem?',
        13: 'Olsem na Devit i no bringim bokis kontrak long em yet long ples long biktaun bilong Devit, tasol em i karim dispela long sait i go long haus bilong man Git Obet-idom.',
        14: 'Na bokis kontrak bilong God i stap yet wantaim famili bilong Obet-idom long haus bilong em tripela mun. Na BIKPELA i blesim haus bilong Obet-idom, na olgeta samting em i gat.',
    },
    14: {
        1: '¶ Nau Hairam, king bilong Tair, i salim ol mausman long Devit, na ol diwai bilong sida, wantaim ol man bilong wokim simen na ol kamda, bilong wokim wanpela haus long em.',
        2: 'Na Devit i kisim save long BIKPELA i bin strongim tok long em i king long bosim Isrel, long wanem, kingdom bilong em God i litimapim antap, bilong wanem, Em i tingim ol manmeri bilong Em Isrel.',
        3: 'Na Devit i kisim ol meri moa long Jerusalem. Na Devit i kamapim ol pikinini man na ol pikinini meri moa.',
        4: 'Nau ol dispela em ol nem bilong ol pikinini bilong em husat em i bin kamapim long Jerusalem, Samua, Sobap, Netan, na Solomon,',
        5: 'Na Ipar, na Elisua, na Elpelet,',
        6: 'Na Noga, na Nefek, na Jafia,',
        7: 'Na Elisama, na Belaida, na Elifalet.',
        8: '¶ Na taim ol lain Filistin i harim long ol i makim Devit king long bosim olgeta Isrel, olgeta lain Filistin i go antap long painim Devit. Na Devit i harim long dispela, na em i go ausait i birua long ol.',
        9: 'Na ol lain Filistin i kam na opim ol yet long ples daun bilong Refaim.',
        10: 'Na Devit i askim long God, i spik, Bai mi go antap i birua long ol lain Filistin? Na bai Yu givim ol i kam long han bilong mi? Na BIKPELA i tokim em, Go antap. Long wanem, Mi bai givim ol i go long han bilong yu.',
        11: 'Olsem na ol i kam antap long Beal-perasim. Na Devit i paitim ol long dispela hap. Nau Devit i tok, God i bin brukim insait antap long ol birua bilong mi long han bilong mi olsem ol wara i bruk i go ausait. Olsem na ol i kolim nem bilong dispela ples Beal-perasim.',
        12: 'Na taim ol i bin lusim ol god bilong ol long dispela hap, Devit i givim wanpela tok strong, na ol i kukim ol olgeta wantaim paia.',
        13: 'Na yet gen ol lain Filistin i opim ol yet ausait long dispela ples daun.',
        14: 'Olsem na Devit i askim gen long God. Na God i tokim em, No ken go antap i bihainim ol. Tanim na lusim ol, na kam antap long ol pas klostu long ol diwai malberi.',
        15: 'Na em bai stap olsem, taim yu bai harim wanpela nois bilong wokabaut insait long antap bilong ol diwai malberi, long nau yu bai go ausait long pait. Long wanem, God i go ausait bipo long yu long paitim ami bilong ol Filistin.',
        16: 'Olsem na Devit i mekim olsem God i tok strong long em. Na ol i paitim ol ami bilong ol Filistin i stat long Gibion, yes, i go inap long Gaser.',
        17: 'Na biknem tru bilong Devit i go ausait long olgeta hap. Na BIKPELA i bringim pret bilong em antap long olgeta kantri.',
    },
    15: {
        1: '¶ Na Devit i wokim ol haus bilong em insait long biktaun bilong Devit, na redim wanpela ples bilong bokis kontrak bilong God, na sanapim wanpela haus sel bilong en.',
        2: 'Nau Devit i tok, I no gat wanpela i ken karim bokis kontrak bilong God, ol lain Livai tasol. Long wanem, BIKPELA i bin makim ol long karim bokis kontrak bilong God, na long wokim wok long Em oltaim oltaim.',
        3: 'Na Devit i bungim olgeta Isrel wantaim long Jerusalem, bilong bringim bokis kontrak bilong BIKPELA i kam antap i go long ples bilong em, dispela em i bin redim bilong en.',
        4: 'Na Devit i bungim ol pikinini bilong Eron, na ol lain Livai.',
        5: 'Bilong ol pikinini man bilong Kohat, Uriel nambawan, na ol brata bilong em 120.',
        6: 'Bilong ol pikinini man bilong Merari, Asea nambawan, na ol brata bilong em 220.',
        7: 'Bilong ol pikinini man bilong Gersom, Joel nambawan, na ol brata bilong em 130.',
        8: 'Bilong ol pikinini man bilong Elisafan, Semea nambawan, na ol brata bilong em 200.',
        9: 'Bilong ol pikinini man bilong Hibron, Eliel nambawan, na ol brata bilong em 80.',
        10: 'Bilong ol pikinini man bilong Usiel, Aminadap nambawan, na ol brata bilong em 112.',
        11: 'Na Devit i singautim long ol pris Sedok na Abaiatar, na long ol lain Livai, long Uriel, Asea, na Joel, Semea, na Eliel, na Aminadap,',
        12: 'Na tokim ol, Yupela stap ol nambawan bilong ol tumbuna papa bilong ol lain Livai. Mekim yupela yet i kamap holi, yupela na ol brata bilong yupela wantaim, inap long yupela i ken bringim bokis kontrak bilong God BIKPELA bilong Isrel i kam antap i go long dispela ples mi bin redim bilong en.',
        13: 'Long wanem, bikos yupela i no mekim dispela long pastaim, BIKPELA, God bilong yumi, i wokim wanpela bruk antap long yumi, long dispela, yumi no painim Em i bihainim rot stret bilong en.',
        14: 'Olsem na ol pris na ol lain Livai i mekim ol yet i kamap holi long bringim bokis kontrak bilong God BIKPELA bilong Isrel i kam antap.',
        15: 'Na ol pikinini bilong ol lain Livai i karim bokis kontrak bilong God antap long ol sol bilong han bilong ol wantaim ol stik bilong en, olsem Moses i tok strong long ol, bilong bihainim tok bilong BIKPELA.',
        16: 'Na Devit i toktok long ol nambawan bilong ol lain Livai bilong makim ol brata bilong ol long stap ol man bilong singim song wantaim ol samting bilong wokim musik, ol kain gita, na ol harp na ol simbol, long wokim nois, taim ol i litimapim nek wantaim amamas tru.',
        17: 'Olsem na ol lain Livai i makim Heman, pikinini man bilong Joel, na bilong ol brata bilong em Esap, pikinini man bilong Berikaia, na bilong ol pikinini man bilong ol brata bilong ol Merari Etan, pikinini man bilong Kusea,',
        18: 'Na wantaim ol brata bilong ol bilong nambatu lain, Sekaraia, Ben, na Jeasiel, na Semiramot, na Jehiel, na Uni, Eliap, na Benea, na Measeaia, na Matitaia, na Elifele, na Mikneaia, na Obet-idom, na Jeiel, ol wasman bilong dua.',
        19: 'Olsem na ol man bilong singim song, Heman, Esap, na Etan, ol i makim bilong wokim nois wantaim ol simbol bilong bras,',
        20: 'Na Sekaraia, na Asiel, na Semiramot, na Jehiel, na Uni, na Eliap, na Measeaia, na Benea, wantaim ol kain gita antap long Alamot,',
        21: 'Na Matitaia, na Elifele, na Mikneaia, na Obet-idom, na Jeiel, na Asasaia, wantaim ol harp antap long Seminit bilong kamap gutpela olgeta.',
        22: 'Na Kenanaia, nambawan bilong ol lain Livai, em i bilong song. Em i skulim ol man long sait bilong song, bilong wanem, em i pulap long save long wokim.',
        23: 'Na Berikaia na Elkana em ol wasman bilong dua bilong bokis kontrak.',
        24: 'Na Sebanaia, na Jehosafat, na Netanel, na Amasai, na Sekaraia, na Benea, na Eleasar, ol pris, i bin winim wantaim ol biugel long ai bilong bokis kontrak bilong God. Na Obet-idom na Jehaia em ol wasman bilong dua bilong bokis kontrak.',
        25: '¶ Olsem na Devit, na ol lapun hetman bilong Isrel, na ol kepten i bosim ol tausen, i go bilong bringim bokis bilong kontrak bilong BIKPELA i kam antap ausait long haus bilong Obet-idom wantaim amamas tru.',
        26: 'Na em i kamap olsem, taim God i helpim ol lain Livai husat i karim bokis bilong kontrak bilong BIKPELA, long ol i ofaim sevenpela bulmakau man na sevenpela meme man.',
        27: 'Na Devit em i werim wanpela longpela saket bilong laplap i naispela tru, na olgeta lain Livai husat i karim bokis kontrak, na ol man bilong singim song, na Kenanaia, bosman bilong song wantaim ol man bilong singim song. Devit tu i gat antap long em wanpela ifat bilong naispela laplap.',
        28: 'Olsem tasol olgeta Isrel i bringim bokis bilong kontrak bilong BIKPELA i kam antap wantaim singaut, na wantaim nois bilong kornet, na wantaim ol biugel, na wantaim ol simbol, na wokim wanpela nois wantaim ol kain gita na ol harp.',
        29: 'Na em i kamap olsem, taim bokis bilong kontrak bilong BIKPELA i kam insait long biktaun bilong Devit, long Mikal, pikinini meri bilong Sol, i lukluk i go ausait long wanpela windo na lukim king Devit i danis na pilai. Na insait long bel bilong em, em i tingim em olsem em i samting nating.',
    },
    16: {
        1: '¶ Olsem na ol i bringim bokis kontrak bilong God, na putim dispela insait long namel bilong dispela haus sel Devit i bin sanapim bilong en. Na ol i ofaim ol sakrifais i kuk olgeta na ol ofa bilong givim bel isi long ai bilong God.',
        2: 'Na taim Devit i bin wokim wanpela pinis bilong ofaim ol ofa i kuk olgeta na ol ofa bilong givim bel isi, em i blesim ol manmeri long nem bilong BIKPELA.',
        3: 'Na em i givim long olgeta wan wan man bilong Isrel, man na meri wantaim, long olgeta wan wan wanpela hap bret, na wanpela gutpela hap bilong abus, na wanpela sospen samting i gat liklik maus bilong wain.',
        4: 'Na em i makim sampela bilong ol lain Livai long wokim wok long ai bilong bokis kontrak bilong BIKPELA, na long raitim, na long tok tenkyu na litimapim God BIKPELA bilong Isrel,',
        5: 'Esap nambawan, na bihain long em Sekaraia, Jeiel, na Semiramot, na Jehiel, na Matitaia, na Eliap, na Benea, na Obet-idom. Na Jeiel i mekim wantaim ol kain gita na wantaim ol harp. Tasol Esap i wokim wanpela nois wantaim ol simbol,',
        6: 'Benea tu na Jahasiel, ol pris, wantaim ol biugel bilong olgeta taim long ai bilong bokis bilong kontrak bilong God.',
        7: '¶ Nau long dispela de Devit i givim pastaim dispela sam bilong tok tenkyu long BIKPELA i go long han bilong Esap na ol brata bilong em.',
        8: 'Givim tok tenkyu i go long BIKPELA, singaut long nem bilong Em, mekim ol manmeri long save long ol wok bilong Em namel long ol manmeri.',
        9: 'Singim song i go long Em, singim ol sam i go long Em, yupela toktok long olgeta wok bilong Em i winim tingting.',
        10: 'Yupela glori insait long nem holi bilong Em. Larim bel bilong ol husat i painim BIKPELA wokim amamas tru.',
        11: 'Painim BIKPELA na strong bilong Em, painim pes bilong Em olgeta taim.',
        12: 'Holim tingting long ol wok bilong Em i mekim man tingting planti, dispela Em i bin wokim, ol samting bilong Em bilong winim tingting, na ol kot bilong maus bilong Em,',
        13: 'O yupela tumbuna pikinini bilong wokboi bilong Em Isrel, yupela ol pikinini bilong Jekop, ol lain Em i makim.',
        14: 'Em i BIKPELA, God bilong yumi. Ol kot bilong Em i stap long olgeta dispela graun.',
        15: 'Yupela mas tingting olgeta taim long kontrak bilong Em, dispela tok Em i tok strong i go long wan tausen lain tumbuna.',
        16: 'Yes, dispela kontrak Em i wokim wantaim Ebraham, na strongpela promis bilong Em i go long Aisak.',
        17: 'Na Em i bin strongim tok long dispela stret long Jekop bilong wanpela lo, na long Isrel bilong wanpela kontrak bilong oltaim oltaim,',
        18: 'I spik, Long yu bai Mi givim hap bilong Kenan, dispela hap skel bilong yu bilong ol samting papa i givim pikinini.',
        19: 'Taim yupela i stap liklik lain tasol, yes, wanpela liklik lain tasol, na ol ausait man insait long en.',
        20: 'Na taim ol i lusim kantri i go long kantri, na i lusim wanpela kingdom i go long narapela lain manmeri,',
        21: 'Em i no larim wanpela man i mekim rong long ol. Yes, em i krosim ol king bilong helpim ol,',
        22: 'I spik, No ken tasim man bilong Mi Mi makim, na no ken bagarapim liklik ol profet bilong Mi.',
        23: 'Singim song i go long BIKPELA, olgeta dispela graun. Soim i go pasin bilong kisim bek bilong Em olgeta wan wan de.',
        24: 'Tokaut long glori bilong Em namel long ol haiden, ol wok bilong Em i mekim man tingting planti namel long olgeta kantri.',
        25: 'Long wanem, BIKPELA em i bikpela, na ol man mas litimapim Em bikpela. Em tu ol man i mas pret long En antap moa long olgeta god.',
        26: 'Long wanem, olgeta god bilong ol manmeri em i ol piksa bilong god giaman. Tasol BIKPELA i wokim ol heven.',
        27: 'Glori na ona i stap long pes bilong Em. Strong na amamas i stap long ples bilong Em.',
        28: 'Givim i go long BIKPELA, yupela ol kandre bilong ol manmeri, givim i go long BIKPELA glori na strong.',
        29: 'Givim i go long BIKPELA dispela glori i inap long nem bilong Em. Bringim wanpela ofa, na kam long ai bilong Em. Lotuim BIKPELA long naispela bilong pasin holi.',
        30: 'Pret long ai bilong Em, olgeta dispela graun. Dispela graun tu bai stap strong, inap long em i no inap muv.',
        31: 'Larim ol heven i stap amamas, na larim dispela graun i wokim amamas tru. Na larim ol man i tok namel long ol kantri, BIKPELA i bosim kingdom.',
        32: 'Larim biksi krai bikpela, na pasin pulap bilong en. Larim ol ples kunai i wokim amamas tru, na olgeta samting i stap insait long ol.',
        33: 'Nau bai ol diwai bilong ples diwai i singaut long pes bilong BIKPELA, bilong wanem, Em i kam bilong jasim dispela graun.',
        34: 'O givim tok tenkyu i go long BIKPELA. Long wanem, Em i gutpela. Long wanem, sori bilong Em i stap strong yet oltaim oltaim.',
        35: 'Na yupela tok, Kisim bek mipela, O God bilong kisim bek bilong mipela, na bungim mipela wantaim, na kisim bek mipela long ol haiden, inap long mipela i ken givim tok tenkyu long nem holi bilong Yu, na glori insait long biknem bilong Yu.',
        36: 'Blesing i stap long God BIKPELA bilong Isrel oltaim oltaim na oltaim. Na olgeta manmeri i tok, Amen, na litimapim nem bilong BIKPELA.',
        37: '¶ Olsem na em i lusim dispela hap long ai bilong bokis bilong kontrak bilong BIKPELA Esap na ol brata bilong em, bilong wokim wok long ai bilong bokis kontrak olgeta taim, olsem wok bilong olgeta wan wan de i gat nid long en,',
        38: 'Na Obet-idom wantaim ol brata bilong ol, 68, Obet-idom tu, pikinini man bilong Jedutun, na Hosa, bilong stap ol wasman bilong dua,',
        39: 'Na pris Sedok, na ol brata bilong em ol pris, long ai bilong haus sel holi bilong BIKPELA long dispela ples antap i stap long Gibion,',
        40: 'Bilong ofaim ol ofa i kuk olgeta i go long BIKPELA antap long alta bilong ofa i kuk olgeta olgeta taim, moning na apinun tru, na bilong mekim bilong bihainim olgeta samting ol i raitim long lo bilong BIKPELA, dispela Em i tok strong long Isrel.',
        41: 'Na wantaim ol Heman na Jedutun, na olgeta arapela husat ol i makim, husat ol i kolim long nem bilong ol, long givim tok tenkyu i go long BIKPELA, bilong wanem, sori bilong Em i stap strong yet oltaim oltaim.',
        42: 'Na wantaim ol Heman na Jedutun wantaim ol biugel na ol simbol bilong ol husat i mas wokim wanpela nois, na wantaim ol samting bilong wokim musik bilong God. Na ol pikinini man bilong Jedutun em ol wasman bilong dua.',
        43: 'Na olgeta manmeri i lusim dispela hap, olgeta wan wan man i go long haus bilong em. Na Devit i go bek bilong blesim haus bilong em.',
    },
    17: {
        1: '¶ Nau em i kamap olsem, taim Devit i sindaun insait long haus bilong em, long Devit i tokim profet Netan, Harim, mi stap insait long wanpela haus bilong ol sida, tasol bokis bilong kontrak bilong BIKPELA i stap yet aninit long ol laplap bilong windo.',
        2: 'Nau Netan i tokim Devit, Wokim olgeta samting i stap insait long bel bilong yu. Long wanem, God i stap wantaim yu.',
        3: 'Na em i kamap olsem long dispela nait stret, long tok bilong God i kam long Netan, i spik,',
        4: 'Go na tokim Devit, wokboi bilong Mi, BIKPELA i tok olsem, Yu no ken wokim wanpela haus long Mi long stap long en.',
        5: 'Long wanem, Mi no bin stap insait long wanpela haus i stat long dispela de Mi bringim Isrel i kam antap inap long tude. Tasol Mi bin go long haus sel i go long haus sel, na long wanpela haus sel holi i go long narapela.',
        6: 'Long wanem hap olgeta Mi bin wokabaut wantaim olgeta Isrel, ating Mi bin tokim wanpela hap tok long wanpela bilong ol jas bilong Isrel, husat Mi tok strong bilong givim kaikai long ol manmeri bilong Mi, i spik, Bilong wanem yupela i no bin wokim long Mi wanpela haus long ol sida?',
        7: 'Olsem na nau yu bai tokim wokboi bilong Mi Devit olsem, BIKPELA bilong ol ami i tok olsem, Mi kisim yu long haus sipsip, yes, long bihainim ol sipsip, inap long yu ken stap hetman long bosim lain manmeri bilong Mi Isrel.',
        8: 'Na Mi bin stap wantaim yu long wanem hap yu bin wokabaut, na Mi bin rausim olgeta olgeta birua bilong yu long ai bilong yu, na Mi bin mekim yu wanpela nem i olsem nem bilong ol bikman tru husat i stap long dispela graun.',
        9: 'Na tu Mi bai makim wanpela ples bilong ol manmeri bilong Mi Isrel, na Mi bai planim ol, na ol bai stap insait long ples bilong ol, na ol bai i no inap muv moa. Na tu ol pikinini bilong pasin nogut bai i no inap bagarapim ol olgeta moa liklik, olsem long stat,',
        10: 'Na i stat long taim long Mi tok strong long ol jas long bosim ol manmeri bilong Mi Isrel. Na moa tu Mi bai daunim olgeta birua bilong yu. Na moa tu Mi bai tokim yu long BIKPELA bai wokim long yu wanpela hauslain.',
        11: 'Na em bai kamap olsem, taim ol de bilong yu i pinis inap long yu mas go long stap wantaim ol tumbuna papa bilong yu, long Mi bai kirapim tumbuna pikinini bilong yu bihain long yu, husat bai stap bilong ol pikinini man bilong yu. Na Mi bai strongim kingdom bilong em.',
        12: 'Em bai wokim long Mi wanpela haus, na Mi bai strongim sia king bilong em oltaim oltaim.',
        13: 'Mi bai stap Papa bilong em, na em bai stap pikinini man bilong Mi. Na Mi bai i no inap tekewe sori bilong Mi i lusim em, olsem Mi kisim dispela long em husat i stap bipo long yu.',
        14: 'Tasol Mi bai putim em insait long haus bilong Mi na insait long kingdom bilong Mi oltaim oltaim. Na sia king bilong em bai Mi strongim bilong oltaim oltaim.',
        15: 'Bilong bihainim olgeta dispela toktok, na bilong bihainim olgeta dispela driman samting, olsem tasol Netan i bin toktok long Devit.',
        16: '¶ Na king Devit i kam na sindaun long ai bilong BIKPELA, na tok, Mi husat, O God BIKPELA, na hauslain bilong mi em i wanem samting, inap long Yu bin bringim mi i kam inap long hia?',
        17: 'Na yet dispela em i wanpela liklik samting long ol ai bilong Yu, O God. Long wanem, Yu bin toktok tu long sait bilong hauslain bilong wokboi bilong Yu long longpela taim i bai kamap yet, na Yu bin tingim mi gut bilong bihainim sindaun bilong wanpela man i gat namba antap, O God BIKPELA.',
        18: 'Devit i ken toktok wanem moa long Yu bilong helpim ona bilong wokboi bilong Yu? Long wanem, Yu save long wokboi bilong Yu.',
        19: 'O BIKPELA, bilong tingim wokboi bilong Yu, na bilong bihainim bel bilong Yu Yet, Yu bin mekim olgeta dispela bikpela samting, taim Yu mekim ol man long save long olgeta dispela bikpela samting.',
        20: 'O BIKPELA, i no gat wanpela i wankain olsem Yu, na tu i no gat wanpela God moa long Yu, bilong bihainim olgeta dispela samting mipela i bin harim wantaim ol ia bilong mipela.',
        21: 'Na wanem wanpela kantri long dispela graun i olsem lain manmeri bilong Yu Isrel, husat God i go bilong baim bek long stap lain manmeri bilong Em Yet, long wokim wanpela nem long Yu i bikpela na samting bilong pretim nogut tru man, taim Yu ranim ol kantri i go ausait long ai bilong lain manmeri bilong Yu, husat Yu bin baim bek ausait long Isip?',
        22: 'Long wanem, lain manmeri bilong Yu Isrel Yu mekim bilong Yu Yet oltaim oltaim. Na Yu, BIKPELA, i kamap God bilong ol.',
        23: 'Olsem na nau, BIKPELA, larim dispela samting long Yu bin toktok long sait bilong wokboi bilong Yu na long sait bilong hauslain bilong em i kamap strong oltaim oltaim, na mekim olsem Yu bin toktok.',
        24: 'Larim dispela, yes, i kamap strong, inap long ol i ken litimapim nem bilong Yu oltaim oltaim, i spik, BIKPELA bilong ol ami em i God bilong Isrel, yes, wanpela God long Isrel. Na larim hauslain bilong Devit, wokboi bilong Yu, kamap strong long ai bilong Yu.',
        25: 'Long wanem, Yu, O God bilong mi, i bin tokim wokboi bilong Yu long Yu bai wokim wanpela hauslain long em. Olsem na wokboi bilong Yu bin lukim insait long bel bilong em long beten long ai bilong Yu.',
        26: 'Na nau, BIKPELA, Yu stap God, na Yu bin promisim pinis dispela gutpela samting i go long wokboi bilong Yu.',
        27: 'Olsem na nau larim dispela amamasim bel bilong Yu long blesim hauslain bilong wokboi bilong Yu, inap long dispela i ken stap long ai bilong Yu oltaim oltaim. Long wanem, Yu blesim, O BIKPELA, na dispela bai gat blesing oltaim oltaim.',
    },
    18: {
        1: '¶ Nau bihain long dispela em i kamap olsem, long Devit i paitim ol Filistin, na daunim ol, na kisim Gat na ol taun bilong en ausait long han bilong ol Filistin.',
        2: 'Na em i paitim Moap. Na ol lain Moap i kamap ol wokboi bilong Devit, na bringim ol presen.',
        3: 'Na Devit i paitim Hadariser, king bilong Soba, i go inap long Hemat, taim em i go bilong strongim hap bilong bosim bilong em klostu long wara Yufretis.',
        4: 'Na Devit i kisim long em wan tausen karis, na 7,000 man i ran long hos, na 20,000 soldia bilong lek. Devit tu i katim rop bilong lek bilong olgeta hos bilong karis, tasol em i holim bek bilong ol 100 karis.',
        5: 'Na taim ol lain Siria bilong Damaskas i kam long helpim Hadariser, king bilong Soba, Devit i kilim i dai bilong ol lain Siria 22,000 man.',
        6: 'Nau Devit i putim ol lain soldia long Siria-damaskas. Na ol lain Siria i kamap ol wokboi bilong Devit, na bringim ol presen. Olsem tasol BIKPELA i mekim Devit stap gut yet long wanem hap em i go.',
        7: 'Na Devit i kisim ol dispela plang gol i stap long ol wokboi bilong Hadariser, na bringim ol long Jerusalem.',
        8: 'Wankain olsem long Tiphat, na long Kun, ol biktaun bilong Hadariser, Devit i bringim planti bras tru, we Solomon i wokim dispela biksi bras, na ol bikpela pos, na ol sospen samting bras long en.',
        9: '¶ Nau taim Tou, king bilong Hemat, i harim long Devit i bin paitim olgeta ami bilong Hadariser, king bilong Soba, olsem wanem,',
        10: 'Em i salim Hadoram, pikinini man bilong em, long king Devit, long askim long em i stap olsem wanem, na bilong tok amamas long em, bilong wanem, em i bin pait birua long Hadariser, na paitim em. (Long wanem, Hadariser i gat bikpela pait wantaim Tou.) Na wantaim Hadoram em i salim olgeta kain kain sospen samting samting bilong gol na silva na bras.',
        11: 'Ol tu king Devit i makim i go long BIKPELA, wantaim ol dispela silva na gol em i bringim long olgeta dispela kantri, long Idom, na long Moap, na long ol pikinini bilong Amon, na long ol Filistin, na long Amalek.',
        12: 'Na moa tu Abisai, pikinini man bilong Seruaia, i kilim i dai bilong ol lain Idom long ples daun bilong sol 18,000.',
        13: 'Na em i putim ol lain soldia long Idom. Na olgeta lain Idom i kamap ol wokboi bilong Devit. Olsem tasol BIKPELA i mekim Devit stap gut yet long wanem hap em i go.',
        14: 'Olsem na Devit i bosim kingdom antap long olgeta Isrel, na mekim kot na stretpela kot namel long olgeta manmeri bilong em.',
        15: 'Na Joap, pikinini man bilong Seruaia, i bosim ami. Na Jehosafat, pikinini man bilong Ahilut, man bilong raitim ol stori.',
        16: 'Na Sedok, pikinini man bilong Ahitup, na Abimelek, pikinini man bilong Abaiatar, em ol pris. Na Savsa em i man bilong rait.',
        17: 'Na Benea, pikinini man bilong Jehoiada, i bosim ol lain Keret na ol lain Pelet. Na ol pikinini man bilong Devit i stap nambawan nabaut long king.',
    },
    19: {
        1: '¶ Nau em i kamap olsem bihain long dispela, long Nehas, king bilong ol pikinini bilong Amon, i dai pinis, na pikinini man bilong em i kisim ples bilong em na bosim kingdom.',
        2: 'Na Devit i tok, Mi bai soim gutpela pasin i go long Hanun, pikinini man bilong Nehas, bilong wanem, papa bilong em i soim gutpela pasin long mi. Na Devit i salim ol mausman bilong givim bel isi long em long sait bilong papa bilong em. Olsem na ol wokboi bilong Devit i kam insait long hap bilong ol pikinini bilong Amon long Hanun, bilong givim bel isi long em.',
        3: 'Tasol ol hetman bilong ol pikinini bilong Amon i tokim Hanun, Yu tingting long Devit i givim ona long papa bilong yu, inap long em i bin salim ol man bilong givim bel isi long yu? Ating i yes long ol wokboi bilong em i kam long yu bilong painimaut tru, na bilong winim, na bilong lukstil long dispela hap?',
        4: 'Olsem na Hanun i kisim ol wokboi bilong Devit, na sevim ol, na katim i go ol klos bilong insait long namel pas klostu stret long ol baksait bilong ol, na salim ol i go.',
        5: 'Nau i gat i go sampela, na ol i tokim Devit long ol i wokim long ol dispela man olsem wanem. Na em i salim tok long bungim ol. Long wanem, ol man i gat bikpela sem. Na king i tok, Stap yet pastaim long Jeriko inap long mausgras bilong yupela i go longpela pinis, na bihain kam bek.',
        6: '¶ Na taim ol pikinini bilong Amon i luksave long ol i bin mekim ol yet kamap samting bilong bagarapim bel tru long Devit, Hanun na ol pikinini bilong Amon i salim wan tausen talen silva bilong baim long ol ol karis na ol man i ran long hos ausait long Mesopotemia, na ausait long Siria-meaka, na ausait long Soba.',
        7: 'Olsem na ol i baim 32,000 karis, na king bilong Meaka na ol lain bilong em, husat i kam na sanapim ol haus sel long ai bilong Medeba. Na ol pikinini bilong Amon i bungim ol yet wantaim long ol biktaun bilong ol, na kam long pait.',
        8: 'Na taim Devit i harim long dispela, em i salim Joap, na olgeta ami bilong ol strongpela man.',
        9: 'Na ol pikinini bilong Amon i kam ausait, na putim pait long lain long ai bilong dua bilong banis bilong biktaun. Na ol king husat i kam wantaim ol i stap ol yet long ples kunai.',
        10: 'Nau taim Joap i luksave pait ol i putim i birua long em fran na long baksait, em i makim ausait long olgeta bilong ol nambawan bilong Isrel, na putim ol long lain i birua long ol lain Siria.',
        11: 'Na olgeta arapela bilong ol lain em i givim i go long han bilong Abisai, brata bilong em, na ol i putim ol yet i lain i birua long ol pikinini bilong Amon.',
        12: 'Na em i tok, Sapos ol lain Siria i stap strong tumas long mi, orait yu bai helpim mi. Tasol sapos ol pikinini bilong Amon i stap strong tumas long yu, orait bai mi helpim yu.',
        13: 'Holimpas gutpela strong bilong pait, na larim yumi wokabaut yumi yet olsem ol strongpela man bilong pait bilong helpim ol lain manmeri bilong yumi, na bilong helpim ol biktaun bilong God bilong yumi. Na larim BIKPELA mekim dispela samting i gutpela long ai bilong Em',
        14: 'Olsem na Joap na ol lain husat i stap wantaim em i go klostu long ai bilong ol lain Siria bilong pait. Na ol i ranawe long ai bilong em.',
        15: 'Na taim ol pikinini bilong Amon i luksave long ol lain Siria i ranawe, ol i ranawe wankain olsem long ai bilong Abisai, brata bilong em, na go insait long biktaun. Nau Joap i kam long Jerusalem.',
        16: 'Na taim ol lain Siria i luksave long ol i kisim taim nogut moa long ai bilong Isrel, ol i salim ol mausman, na pulim i kam ausait ol lain Siria husat i stap hapsait long riva. Na Sofak, kepten bilong ami bilong Hadariser, i go pas long ol.',
        17: 'Na ol i tokim Devit long dispela. Na em i bungim olgeta Isrel, na brukim Jordan, na kam antap long ol, na putim pait long lain i birua long ol. Olsem na taim Devit i bin putim pait long lain i birua long ol lain Siria, ol i pait wantaim em.',
        18: 'Tasol ol lain Siria i ranawe long ai bilong Isrel. Na Devit i kilim i dai bilong ol Siria 7,000 man husat i pait insait long ol karis, na 40,000 man bilong pait long lek, na kilim i dai Sofak, kepten bilong ami.',
        19: 'Na taim ol wokboi bilong Hadariser i luksave long ol i kisim taim nogut moa long ai bilong Isrel, ol i wokim bel isi wantaim Devit, na kamap ol wokboi bilong em. Na tu ol lain Siria i no gat laik long helpim ol pikinini bilong Amon moa liklik.',
    },
    20: {
        1: '¶ Na em i kamap olsem, long bihain long yia i pinis, long taim bilong ol king bilong go ausait bilong pait, Joap i go pas ausait wantaim pawa bilong ami, na bagarapim olgeta kantri bilong ol pikinini bilong Amon, na kam na pasim Raba. Tasol Devit i stap yet long Jerusalem. Na Joap i paitim Raba, na bagarapim dispela olgeta.',
        2: 'Na Devit i kisim hat king bilong king bilong ol long het bilong em, na painimaut pinis long dispela i skel olsem wanpela talen gol, na i gat ol ston i dia tumas insait long en. Na ol i putim dispela antap long het bilong Devit. Na em i bringim tu planti kago bilong pait moa yet i kam ausait long dispela biktaun.',
        3: 'Na em i bringim i kam ausait ol manmeri husat i stap insait long en, na katim ol wantaim ol so, na wantaim ol ain bilong brukim graun, na wantaim ol akis. Yes, olsem tasol Devit i mekim long olgeta biktaun bilong ol pikinini bilong Amon. Na Devit na olgeta manmeri i kam bek long Jerusalem.',
        4: '¶ Na em i kamap olsem bihain long dispela, long bikpela pait i kirap long Geser wantaim ol Filistin. Long dispela taim man Husa Sibekai i kilim i dai Sipai, husat i bilong ol pikinini bilong dispela traipela man. Na ol i stap aninit.',
        5: 'Na i gat bikpela pait gen wantaim ol Filistin. Na Elhanan, pikinini man bilong Jair, i kilim i dai Lami, brata bilong man Git Golaiat, husat handel bilong spia bilong tromoi bilong em i olsem wanpela bikpela hap diwai bilong man bilong wokim laplap.',
        6: 'Na yet gen i gat bikpela pait long Gat, we i gat wanpela man i longpela tru, husat ol pinga na ol pinga bilong lek bilong en em i 24, sikispela long wan wan han, na sikispela long wan wan lek. Na em tu em pikinini man bilong dispela traipela man.',
        7: 'Tasol taim em i duim Isrel, Jonatan, pikinini man bilong Simea, brata bilong Devit, i kilim em i dai.',
        8: 'Ol dispela meri i karim long dispela traipela man long Gat. Na ol i pundaun long han bilong Devit, na long han bilong ol wokboi bilong em.',
    },
    21: {
        1: '¶ Na Seten i sanap i birua long Isrel, na skrapim bel bilong Devit long kaunim Isrel.',
        2: 'Na Devit i tokim Joap na ol hetman bilong ol manmeri, Go, kaunim Isrel i stat long Biar-siba, yes, i go inap long Dan. Na bringim namba bilong ol i kam long mi, inap long mi ken save long en.',
        3: 'Na Joap i bekim tok, BIKPELA i ken mekim ol manmeri bilong Em i 100 taims planti moa olsem ol i stap. Tasol, king, bikman bilong mi, ating i yes long olgeta i ol wokboi bilong bikman bilong mi? Bilong wanem nau bikman bilong mi i strong long dispela samting? Bilong wanem em i laik stap wanpela as bilong Isrel i sakim lo?',
        4: 'Tasol tok bilong king i winim Joap. Olsem na Joap i lusim dispela hap, na em i go namel long olgeta hap bilong Isrel, na kam long Jerusalem.',
        5: 'Na Joap i givim namba olgeta bilong namba bilong ol manmeri i go long Devit. Na olgeta man bilong Isrel em 1,100,000 man husat i kamautim bainat. Na Juda em 470,000 man husat i kamautim bainat.',
        6: 'Tasol Livai na Benjamin em i no kaunim namel long ol. Long wanem, tok bilong king i sting long Joap.',
        7: '¶ Na God i no amamas long dispela samting. Olsem na Em i paitim Isrel.',
        8: 'Na Devit i tokim God, Mi bin sin bikpela, bilong wanem, mi bin mekim dispela samting. Tasol nau, mi askim Yu long daun pasin, rausim i go sin nogut bilong wokboi bilong Yu. Long wanem, mi bin mekim kranki pasin tru.',
        9: 'Na BIKPELA i tokim Gat, sia bilong Devit, i spik,',
        10: 'Go na tokim Devit, i spik, BIKPELA i tok olsem, Mi ken givim yu long tripela samting. Yu makim wanpela bilong ol, inap long Mi ken mekim dispela long yu.',
        11: 'Olsem na Gat i kam long Devit, na tokim em, BIKPELA i tok olsem, Yu makim',
        12: 'Tripela yia bikpela taim hangre, o tripela mun long kisim bagarap olgeta long ai bilong ol birua bilong yu, taim bainat bilong ol birua bilong yu i kamap long yu, o sapos nogat, tripela de bainat bilong BIKPELA, yes sik nogut, bai stap long dispela hap, na ensel bilong BIKPELA i bagarapim olgeta long olgeta hap bilong hap arere bilong Isrel. Olsem na nau, givim tingting bilong yu yet long wanem tok mi bai bringim gen long Em husat i salim mi.',
        13: 'Na Devit i tokim Gat, Mi stap long wanpela ples i liklik tru. Larim mi pundaun nau i go long han bilong BIKPELA. Long wanem, ol sori bilong Em em i bikpela tru. Tasol i no ken larim mi pundaun i go long han bilong man.',
        14: 'Olsem na BIKPELA i salim sik nogut antap long Isrel. Na i gat i pundaun bilong Isrel 70,000 man.',
        15: 'Na God i salim wanpela ensel i go long Jerusalem long bagarapim dispela olgeta. Na taim em i wok long bagarapim olgeta, BIKPELA i lukim, na Em i tanim bel long dispela samting nogut, na tokim ensel husat i bagarapim olgeta, Em inap, pasim nau han bilong yu. Na ensel bilong BIKPELA i sanap klostu long plua bilong klinim wit bilong man Jebus Ornan.',
        16: 'Na Devit i litimapim tupela ai bilong em, na lukim ensel bilong BIKPELA i sanap namel long dispela graun na heven, taim em i gat wanpela bainat em i kamautim long paus long han bilong em i op antap long Jerusalem. Nau Devit na ol lapun hetman bilong Isrel, husat i werim bek laplap, i pundaun long ol pes bilong ol.',
        17: 'Na Devit i tokim God, Ating i yes long em i mi husat i tok strong long kaunim ol manmeri? Yes, em i mi husat tru tru i bin mekim sin na mekim pasin nogut. Tasol long sait bilong ol dispela sipsip, ol i bin mekim wanem? Larim han bilong Yu, mi askim Yu plis, O BIKPELA, God bilong Mi, stap antap long mi, na antap long hauslain bilong tumbuna papa bilong mi, tasol i no ken stap antap long ol manmeri bilong Yu, inap long ol i ken kisim sik nogut.',
        18: '¶ Nau ensel bilong BIKPELA i tok strong long Gat long tokim Devit, long Devit i mas i go antap, na sanapim wanpela alta i go long BIKPELA long plua bilong klinim wit bilong man Jebus Ornan.',
        19: 'Na Devit i go antap, long toktok bilong Gat, dispela em i tokim em long nem bilong BIKPELA.',
        20: 'Na Ornan i tanim i go bek, na lukim dispela ensel. Na fopela pikinini man bilong em wantaim em i haitim ol yet. Nau Ornan i wok long klinim wit.',
        21: 'Na taim Devit i kam long Ornan, Ornan i lukluk na lukim Devit, na go ausait long plua bilong klinim wit, na lindaunim em yet long Devit wantaim pes bilong em i go long graun.',
        22: 'Nau Devit i tokim Ornan, Tok orait long mi long ples bilong dispela plua bilong klinim wit, inap long mi ken wokim wanpela alta insait long en i go long BIKPELA. Yu bai tok orait long mi long pe olgeta bilong en, inap long God i ken pinisim dispela sik nogut long ol manmeri.',
        23: 'Na Ornan i tokim Devit, Kisim dispela i go long yu, na larim king, bikman bilong mi, mekim dispela samting em i gutpela long tupela ai bilong em. Harim, mi givim yu nating ol bulmakau man tu bilong ol ofa i kuk olgeta, na ol samting bilong klinim wit long diwai, na wit bilong ofa bilong kaikai. Mi givim nating dispela olgeta.',
        24: 'Na king Devit i tokim Ornan, Nogat. Tasol tru tumas, mi bai baim dispela long pe olgeta bilong en. Long wanem, mi bai i no inap kisim dispela samting i bilong yu bilong givim long BIKPELA, o ofaim ol ofa i kuk olgeta sapos i no gat kos bilong en.',
        25: 'Olsem na Devit i givim long Ornan, bilong baim dispela ples, 600 sekel bilong gol long skel.',
        26: 'Na Devit i wokim long dispela hap wanpela alta i go long BIKPELA, na ofaim ol ofa i kuk olgeta na ol ofa bilong givim bel isi, na em i singaut long nem bilong BIKPELA. Na Em i bekim em long heven wantaim paia antap long alta bilong ofa i kuk olgeta.',
        27: 'Na BIKPELA i tok strong long dispela ensel, na em i putim bainat bilong em gen i go long paus bilong en.',
        28: 'Long dispela taim, taim Devit i luksave long BIKPELA i bin bekim em long plua bilong klinim wit bilong man Jebus Ornan, orait em i wokim sakrifais long dispela hap.',
        29: 'Long wanem, haus sel holi bilong BIKPELA, dispela Moses i wokim long ples i no gat man, na alta bilong ofa i kuk olgeta, i stap long dispela taim long dispela ples antap long Gibion.',
        30: 'Tasol Devit i no inap long go long ai bilong en long askim long God. Long wanem, em i pret, bilong wanem, bainat bilong ensel bilong BIKPELA i stap.',
    },
    22: {
        1: '¶ Nau Devit i tok, Dispela em i haus bilong God BIKPELA, na dispela em i alta bilong ofa i kuk olgeta bilong Isrel.',
        2: 'Na Devit i tok strong long bungim ol ausait man wantaim husat i stap long hap bilong Isrel. Na em i putim ol man bilong wok wantaim ston long katim ol ston man i wokim long wokim haus bilong God.',
        3: 'Na Devit i redim ain i planti moa yet bilong ol nil bilong ol dua bilong ol dua bilong banis, na bilong ol samting ol i joinim wantaim, na bras i planti moa yet i no gat namba bilong hevi bilong en,',
        4: 'Na tu ol diwai sida i planti moa yet. Long wanem, ol lain Saidon na ol bilong Tair i bringim planti diwai sida long Devit.',
        5: 'Na Devit i tok, Solomon, pikinini man bilong mi, em i yangpela na em i no strong, na dispela haus em bai wokim bilong BIKPELA i mas stap samting bilong litimapim nem planti moa yet, long biknem tru na long glori long olgeta hap long olgeta kantri. Olsem na nau mi bai wokim ol wok bilong redim bilong dispela. Olsem na Devit i redim planti moa yet bipo em i dai.',
        6: '¶ Nau em i singautim Solomon, pikinini man bilong em, na givim tok long em long wokim wanpela haus bilong God BIKPELA bilong Isrel.',
        7: 'Na Devit i tokim Solomon, Pikinini man bilong mi, long sait bilong mi, em i stap insait long tingting bilong mi long wokim wanpela haus long nem bilong BIKPELA, God bilong mi.',
        8: 'Tasol tok bilong BIKPELA i kam long mi, i spik, Yu bin kapsaitim blut i planti moa yet, na yu bin wokim ol bikpela pait i bikpela. Yu no ken wokim wanpela haus long nem bilong Mi, bilong wanem, yu bin kapsaitim planti blut antap long dispela graun long ai bilong Mi.',
        9: 'Lukim, wanpela pikinini man meri bai karim long yu, husat bai stap wanpela man bilong malolo. Na Mi bai givim malolo long em long olgeta birua bilong em raun nabaut. Long wanem, nem bilong em bai stap Solomon, na Mi bai givim bel isi na gutpela sindaun long Isrel long ol de bilong em.',
        10: 'Em bai wokim wanpela haus long nem bilong Mi. Na em bai stap pikinini man bilong Mi, na Mi bai stap Papa bilong em. Na Mi bai strongim sia king bilong kingdom bilong em long bosim Isrel oltaim oltaim.',
        11: 'Nau, pikinini man bilong mi, BIKPELA i ken stap wantaim yu. Na yu ken kamap gutpela, na wokim haus bilong BIKPELA, God bilong yu, olsem Em i bin toktok long sait bilong yu.',
        12: 'Tasol BIKPELA i ken givim yu save tru na gutpela save, na givim tok long yu long sait bilong Isrel, inap long yu ken holimpas lo bilong BIKPELA, God bilong yu.',
        13: 'Nau bai yu ken kamap gutpela, sapos yu was gut long inapim ol lo Em i raitim na ol dispela kot BIKPELA i givim tok long Moses long en long sait bilong Isrel. Stap strong, na holimpas gutpela strong bilong pait. No ken pret tru, o wari planti.',
        14: 'Nau, lukim, insait long trabel bilong mi mi bin redim bilong haus bilong BIKPELA 100,000 talen gol, na 1,000 talen silva, na long bras na ain i no gat namba bilong hevi bilong ol. Long wanem, em i stap planti moa yet. Diwai tu na ston mi bin redim. Na Yu ken skruim moa long en.',
        15: 'Na moa tu i gat ol wokman wantaim yu i planti moa yet, ol man bilong katim na ol wokman bilong ston na diwai, na olgeta kain kain saveman stret bilong olgeta wan wan kain wok.',
        16: 'Bilong gol, silva, na bras, na ain, i no gat namba. Olsem na kirap, na wokim wok, na BIKPELA i ken stap wantaim yu.',
        17: '¶ Devit tu i tok strong long olgeta hetman bilong Isrel long helpim Solomon, pikinini man bilong em, i spik,',
        18: 'Ating i yes long BIKPELA, God bilong yupela, i stap wantaim yupela? Na ating i yes long Em i givim yupela malolo long olgeta wan wan sait? Long wanem, Em i bin givim ol husat i stap long dispela hap i go long han bilong mi. Na dispela hap mi daunim pinis long ai bilong BIKPELA, na long ai bilong ol manmeri bilong Em.',
        19: 'Nau putim bel bilong yupela na tewel bilong yupela long painim BIKPELA, God bilong yupela. Olsem na kirap, na yupela wokim rum holi bilong God BIKPELA, long bringim bokis bilong kontrak bilong BIKPELA, na ol sospen samting holi bilong God, i go insait long dispela haus yupela bai wokim long nem bilong BIKPELA.',
    },
    23: {
        1: '¶ Olsem na taim Devit i lapun na pulap long ol de, em i mekim Solomon, pikinini man bilong em, king long bosim Isrel.',
        2: 'Na em i bungim olgeta hetman bilong Isrel wantaim, wantaim ol pris na ol lain Livai.',
        3: 'Nau ol lain Livai ol i kaunim i stat long 30 krismas na i go antap. Na namba bilong ol, long kaunim bilong ol, olgeta wan wan man, em 38,000.',
        4: 'Bilong dispela, 24,000 ol i go bilong putim wok bilong haus bilong BIKPELA long fran. Na 6,000 em ol ofisa na ol jas.',
        5: 'Na moa tu 4,000 em ol wasman bilong dua. Na 4,000 i litimapim nem bilong BIKPELA wantaim ol dispela samting bilong wokim musik mi wokim pinis, Devit i tok, long litimapim God wantaim ol.',
        6: 'Na Devit i brukim ol i go long ol taim bilong wok namel long ol pikinini man bilong Livai, ol i olsem, Gerson, Kohat, na Merari.',
        7: 'Bilong ol lain Gerson em, Leadan, na Simei.',
        8: 'Ol pikinini man bilong Leadan, Jehiel nambawan, na Setam, na Joel, tripela.',
        9: 'Ol pikinini man bilong Simei, Selomit, na Hasiel, na Haran, tripela. Ol dispela em ol nambawan bilong ol tumbuna papa bilong Leadan.',
        10: 'Na ol pikinini man bilong Simei em, Jahat, Sina, na Jeus, na Beraia. Ol dispela fopela em ol pikinini man bilong Simei.',
        11: 'Na Jahat em i nambawan, na Sisa namba tu. Tasol Jeus na Beraia i no gat planti pikinini man, olsem na ol i stap long wanpela kaunim, bilong bihainim hauslain bilong tumbuna papa bilong ol.',
        12: 'Ol pikinini man bilong Kohat, Amram, Ishar, Hibron, na Usiel, fopela.',
        13: 'Ol pikinini man bilong Amram, Eron na Moses. Na Eron God i brukim, inap long em i ken mekim i kamap holi ol samting i holi moa olgeta, em na ol pikinini man bilong em oltaim oltaim, long kukim insens long ai bilong BIKPELA, long wokim wok long Em, na long blesim long nem bilong Em oltaim oltaim.',
        14: 'Nau long sait bilong Moses, man bilong God, ol pikinini man bilong em ol i kolim bilong lain Livai.',
        15: 'Ol pikinini man bilong Moses em, Gersom, na Eleasar.',
        16: 'Bilong ol pikinini man bilong Gersom, Sebyuel em i nambawan.',
        17: 'Na ol pikinini man bilong Eleasar em, Rehabaia nambawan. Na Eleasar i no gat ol arapela pikinini man, tasol ol pikinini man bilong Rehabaia em i planti tru.',
        18: 'Ol pikinini man bilong Ishar, Selomit nambawan.',
        19: 'Bilong ol pikinini man bilong Hibron, Jeraia namba wan, Amaraia namba tu, Jahasiel namba tri, na Jekameam namba foa.',
        20: 'Bilong ol pikinini man bilong Usiel, Mika namba wan, na Jesaia namba tu.',
        21: 'Ol pikinini man bilong Merari, Mali, na Musi. Ol pikinini man bilong Mali, Eleasar, na Kis.',
        22: 'Na Eleasar i dai pinis, na em i no gat ol pikinini man, ol pikinini meri tasol. Na ol brata bilong ol, ol pikinini man bilong Kis, i kisim ol.',
        23: 'Ol pikinini man bilong Musi, Mali, na Eder, na Jeremot, tripela.',
        24: '¶ Ol dispela em ol pikinini man bilong Livai i bihainim hauslain bilong ol tumbuna papa bilong ol. Yes, ol nambawan bilong ol tumbuna papa bilong ol, olsem ol i kaunim long namba bilong ol nem bilong ol long ol kaunim bilong ol, husat i mekim wok bilong wok bilong haus bilong BIKPELA, i stat long 20 krismas na i go antap.',
        25: 'Long wanem, Devit i tok, God BIKPELA bilong Isrel i bin givim malolo long ol lain bilong Em, inap long ol i ken stap long Jerusalem oltaim oltaim.',
        26: 'Na tu long ol lain Livai. Ol bai i no inap karim moa haus sel holi, o sampela sospen samting bilong en long wok bilong en.',
        27: 'Long wanem, long ol las hap tok bilong Devit ol i kaunim ol lain Livai i stat long 20 krismas na antap.',
        28: 'Bilong wanem, wok bilong ol em i bilong mekim wok long ol pikinini man bilong Eron long wok bilong haus bilong BIKPELA, long ol ples op, na long ol rum, na long ol wok bilong mekim olgeta samting holi i kamap klin tru, na wok bilong wok bilong haus bilong God,',
        29: 'Bilong bret bilong soim, na bilong naispela plaua bilong ofa bilong kaikai, na bilong ol kek i no gat yis, na bilong dispela samting ol i kukim long sospen, na bilong dispela samting ol i praim, na bilong olgeta kain kain bilong skel na sais wantaim,',
        30: 'Na bilong sanap olgeta wan wan moning bilong tok tenkyu na litimapim nem bilong BIKPELA, na wankain olsem long apinun tru,',
        31: 'Na bilong ofaim olgeta sakrifais i kuk olgeta i go long BIKPELA long ol sabat, long ol nupela mun, na long ol bikpela kaikai ol i makim, long namba, bilong bihainim oda God i tok strong long ol, olgeta taim long ai bilong BIKPELA,',
        32: 'Na long ol i ken holimpas wok bilong haus holi bilong bung bilong ol manmeri, na wok bilong ples holi, na wok bilong ol pikinini man bilong Eron, ol brata bilong ol, insait long wok bilong haus bilong BIKPELA.',
    },
    24: {
        1: '¶ Nau ol dispela em ol bruk bilong ol pikinini man bilong Eron. Ol pikinini man bilong Eron, Nedap, na Abihu, Eleasar, na Itamar.',
        2: 'Tasol Nedap na Abihu i dai pinis bipo long papa bilong ol, na ol i no gat ol pikinini. Olsem na Eleasar na Itamar i mekim wok long wok bilong pris.',
        3: 'Na Devit i tilim ol, Sedok bilong ol pikinini man bilong Eleasar, na Ahimelek bilong ol pikinini man bilong Itamar wantaim, bilong bihainim ol wok bilong wok bilong ol.',
        4: 'Na i gat moa nambawan man ol i lukim bilong ol pikinini man bilong Eleasar long i gat bilong Itamar. Na ol i bruk olsem. Namel long ol pikinini man bilong Eleasar i gat 16 nambawan man bilong hauslain bilong ol tumbuna papa bilong ol, na etpela namel long ol pikinini man bilong Itamar bilong bihainim hauslain bilong ol tumbuna papa bilong ol.',
        5: 'Olsem tasol ol i brukim ol long satu, wanpela kain wantaim narapela. Long wanem, ol nambawan gavman bilong rum holi, na ol nambawan gavman bilong haus bilong God, em i bilong ol pikinini man bilong Eleasar, na bilong ol pikinini man bilong Itamar.',
        6: 'Na Semea, pikinini man bilong man bilong rait Netanel, wanpela bilong ol lain Livai, i raitim ol long ai bilong king, na ol hetman, na pris Sedok, na Ahimelek, pikinini man bilong Abaiatar, na long ai bilong ol nambawan bilong ol tumbuna papa bilong ol pris na ol lain Livai. Wanpela nambawan hauslain husat ol i kisim bilong Eleasar, na wanpela ol i kisim bilong Itamar.',
        7: 'Nau namba wan satu i kam ausait long Jehoiarip, namba tu long Jedea,',
        8: 'Namba tri long Harim, namba foa long Seorim,',
        9: 'Namba faiv long Malkaisa, namba sikis long Misamin,',
        10: 'Namba seven long Hakos, namba et long Abaisa,',
        11: 'Namba nain long Jesua, namba ten long Sekanaia,',
        12: 'Namba 11 long Eliasip, namba 12 long Jakim,',
        13: 'Namba 13 long Hupa, namba 14 long Jesebeap,',
        14: 'Namba 15 long Bilga, namba 16 long Imer,',
        15: 'Namba 17 long Hesir, namba 18 long Afsis,',
        16: 'Namba 19 long Petahaia, namba 20 long Jehesekel,',
        17: 'Namba 21 long Jakin, namba 22 long Gamul,',
        18: 'Namba 23 long Delea, namba 24 long Measaia.',
        19: 'Ol dispela em ol taim bilong ol insait long wok bilong ol long kam insait long haus bilong BIKPELA, bilong bihainim kastam bilong ol, aninit long Eron, tumbuna papa bilong ol, olsem God BIKPELA bilong Isrel i bin tok strong long em.',
        20: '¶ Na olgeta arapela pikinini man bilong Livai em ol dispela. Bilong ol pikinini man bilong Amram, Subael. Bilong ol pikinini man bilong Subael, Jedeaia.',
        21: 'Long sait bilong Rehabaia, bilong ol pikinini man bilong Rehabaia, namba wan em Isaia.',
        22: 'Bilong ol lain Ishar, Selomot. Bilong ol pikinini man bilong Selomot, Jahat.',
        23: 'Na bilong ol pikinini man bilong Hibron, Jeraia namba wan, Amaraia namba tu, Jahasiel namba tri, Jekameam namba foa.',
        24: 'Bilong ol pikinini man bilong Usiel, Maika. Bilong ol pikinini man bilong Maika, Samir,',
        25: 'Brata bilong Maika em Isaia. Bilong ol pikinini man bilong Isaia, Sekaraia.',
        26: 'Ol pikinini man bilong Merari em Mali na Musi. Ol pikinini man bilong Jeasaia, Beno.',
        27: 'Ol pikinini man bilong Merari long Jeasaia, Beno, na Soham, na Sakur, na Ipri.',
        28: 'Bilong Mali Eleasar i kam, husat i no gat ol pikinini man.',
        29: 'Long sait bilong Kis, pikinini man bilong Kis em Jeramel.',
        30: 'Ol pikinini man tu bilong Musi, Mali, na Eder, na Jerimot. Ol dispela em ol pikinini man bilong ol lain Livai i bihainim hauslain bilong ol tumbuna papa bilong ol.',
        31: 'Wankain olsem, ol dispela i tromoi satu pas klostu long ol brata bilong ol, ol pikinini man bilong Eron, long pes bilong king Devit, na Sedok, na Ahimelek, na ol nambawan bilong ol tumbuna papa bilong ol pris na ol lain Livai, yes, ol nambawan tumbuna papa i pas klostu long ol brata bilong ol i yangpela moa.',
    },
    25: {
        1: '¶ Na moa tu Devit na ol kepten bilong ami i brukim i go long wok bilong ol pikinini man bilong Esap, na bilong Heman, na bilong Jedutun, husat i ken autim tok profet wantaim ol harp, wantaim ol kain gita, na wantaim ol simbol. Na namba bilong ol wokman bilong bihainim wok bilong ol em,',
        2: 'Bilong ol pikinini man bilong Esap, Sakur, na Josep, na Netanaia, na Asarela, ol pikinini man bilong Esap aninit long han bilong Esap, husat i autim tok profet bilong bihainim oda bilong king.',
        3: 'Bilong Jedutun, ol pikinini man bilong Jedutun, Gedalaia, na Seri, na Jesea, Hasabaia, na Matitaia, sikispela, aninit long han bilong papa bilong ol Jedutun, husat i autim tok profet wantaim wanpela harp, bilong givim tok tenkyu na bilong litimapim nem bilong BIKPELA.',
        4: 'Bilong Heman, ol pikinini man bilong Heman, Bukaia, Matanaia, Usiel, Sebyuel, na Jerimot, Hananaia, Hanani, Eliata, Gidalti, na Romamtieser, Josbekasa, Maloti, Hotir, na Mahasiot.',
        5: 'Olgeta dispela em ol pikinini man bilong Heman, sia bilong king long ol tok bilong God, long litimapim kom. Na God i givim Heman 14 pikinini man na tripela pikinini meri.',
        6: 'Olgeta dispela i stap aninit long han bilong papa bilong ol bilong song insait long haus bilong BIKPELA, wantaim ol simbol, ol kain gita, na ol harp, bilong wok bilong haus bilong God, bilong bihainim oda bilong king i go long Esap, Jedutun, na Heman.',
        7: 'Olsem na namba bilong ol, wantaim ol brata bilong ol husat ol i skulim long ol song bilong BIKPELA, yes, olgeta husat i gat save stret, em 288.',
        8: '¶ Na ol i tromoi satu, rum i pas klostu long rum, liklik wankain olsem bikpela, tisa wankain olsem sumatin.',
        9: 'Nau namba wan satu i kam ausait bilong Esap long Josep, namba tu long Gedalaia, husat wantaim ol brata bilong em na ol pikinini man bilong em em 12,',
        10: 'Namba tri long Sakur, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        11: 'Namba foa long Isri, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        12: 'Namba faiv long Netanaia, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        13: 'Namba sikis long Bukaia, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        14: 'Namba seven long Jesarela, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        15: 'Namba et long Jesea, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        16: 'Namba nain long Matanaia, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        17: 'Namba ten long Simei, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        18: 'Namba 11 long Asarel, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        19: 'Namba 12 long Hasabaia, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        20: 'Namba 13 long Subael, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        21: 'Namba 14 long Matitaia, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        22: 'Namba 15 long Jeremot, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        23: 'Namba 16 long Hananaia, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        24: 'Namba 17 long Josbekasa, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        25: 'Namba 18 long Hanani, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        26: 'Namba 19 long Maloti, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        27: 'Namba 20 long Eliata, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        28: 'Namba 21 long Hotir, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        29: 'Namba 22 long Gidalti, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        30: 'Namba 23 long Mahasiot, em, ol pikinini man bilong em, na ol brata bilong em, em 12,',
        31: 'Namba 24 long Romamtieser, em, ol pikinini man bilong em, na ol brata bilong em, em 12.',
    },
    26: {
        1: '¶ Long sait bilong ol bruk bilong ol wasman bilong dua, bilong ol lain Kore em Meselemaia, pikinini man bilong Kore, bilong ol pikinini man bilong Esap.',
        2: 'Na ol pikinini man bilong Meselemaia em, Sekaraia namba wan pikinini, Jediel namba tu, Sebadaia namba tri, na Jatniel namba foa,',
        3: 'Ilam namba faiv, Jehohanan namba sikis, Elioenai namba seven.',
        4: 'Na moa tu ol pikinini man bilong Obet-idom em, Semea namba wan pikinini, Jehosabat namba tu, Joa namba tri, Sakar namba foa, na Netanel namba faiv,',
        5: 'Amiel namba sikis, Isakar namba seven, Peultai namba et. Long wanem, God i blesim em.',
        6: 'Na tu long Semea, pikinini man bilong em, meri i karim ol pikinini man, husat i bosim olgeta hap bilong hauslain bilong tumbuna papa bilong ol. Long wanem, ol i ol strongpela man tru bilong pait.',
        7: 'Ol pikinini man bilong Semea, Otni, na Refael, na Obet, Elsabat, husat ol brata bilong ol em ol strongpela man, Elihu, na Semakaia.',
        8: 'Olgeta dispela bilong ol pikinini man bilong Obet-idom, ol na ol pikinini man bilong ol na ol brata bilong ol, ol man i inap bilong stap strong bilong wok, em 62 bilong Obet-idom.',
        9: 'Na Meselemaia i gat ol pikinini man na ol brata, ol strongpela man, 18.',
        10: 'Na tu Hosa, bilong ol pikinini bilong Merari, i gat ol pikinini man, Simri nambawan, (long wanem, maski em i no namba wan pikinini, yet papa bilong em i mekim em i kamap nambawan,)',
        11: 'Hilkaia namba tu, Tebalaia namba tri, Sekaraia namba foa. Olgeta pikinini man na brata bilong Hosa em 13.',
        12: 'Namel long ol dispela em ol bruk bilong ol wasman bilong dua, yes, namel long ol nambawan man, husat i gat ol rum wanpela i pas klostu long narapela, bilong wokim wok insait long haus bilong BIKPELA.',
        13: 'Na ol i tromoi satu, man nating wankain olsem bikman, bilong bihainim hauslain bilong ol tumbuna papa bilong ol, bilong olgeta wan wan dua bilong banis.',
        14: 'Na satu i pundaun long hap is go long Selemaia. Nau long Sekaraia, pikinini man bilong em, wanpela man i gat save tru bilong givim tok helpim, ol i tromoi satu. Na hap skel bilong em i kam ausait long hap i go long hap not.',
        15: 'Long Obet-idom long hap i go long hap saut, na long ol pikinini man bilong em hauslain bilong Asupim.',
        16: 'Long Supim na Hosa satu i kam ausait long hap i go long hap wes, wantaim dua bilong banis Saleket, klostu long strongpela rot bilong i go antap, rum i pas klostu long rum.',
        17: 'I go long hap is em sikispela lain Livai, i go long hap not fopela long wan wan de, i go long hap saut, fopela long wan wan de, na i go long Asupim tupela na tu pela.',
        18: 'Long Parbar i go long hap wes, fopela long strongpela rot, na tu pela long Parbar.',
        19: 'Ol dispela em i ol bruk bilong ol wasman bilong ol dua namel long ol pikinini man bilong Kore, na namel long ol pikinini man bilong Merari.',
        20: '¶ Na bilong ol lain Livai, Ahaisa em i bosim ol samting i dia tru bilong haus bilong God, na bosim ol samting i dia tru bilong ol samting ol man i makim.',
        21: 'Olsem long sait bilong ol pikinini man bilong Leadan, ol pikinini man bilong man Gerson Leadan, ol nambawan papa, yes, bilong man Gerson Leadan, em Jehieli.',
        22: 'Ol pikinini man bilong Jehieli, Setam, na Joel, brata bilong em, husat ol i bosim ol samting i dia tru bilong haus bilong BIKPELA.',
        23: 'Bilong ol lain Amram, na ol lain Ishar, ol lain Hibron, na ol lain Usiel,',
        24: 'Na Sebyuel, pikinini man bilong Gersom, pikinini man bilong Moses, em i hetman bilong ol samting i dia tru.',
        25: 'Na ol brata bilong em long Eleasar, Rehabaia, pikinini man bilong em, na Jesea, pikinini man bilong em, na Joram, na pikinini man bilong em, na Sikri, pikinini man bilong em, na Selomit, pikinini man bilong em.',
        26: 'Husat Selomit na ol brata bilong en em i bosim olgeta samting i dia tru bilong ol samting ol man i makim, dispela king Devit, na ol nambawan papa, ol kepten long bosim ol tausen na ol handret, na ol kepten bilong ami, i bin makim.',
        27: 'I kam ausait long ol kago bilong pait ol i winim long ol pait, ol i bin makim bilong lukautim gut haus bilong BIKPELA.',
        28: 'Na olgeta samting sia Samyuel, na Sol, pikinini man bilong Kis, na Apner, pikinini man bilong Ner, na Joap, pikinini man bilong Seruaia, i bin makim. Na husat man i bin makim wanpela samting, em i stap aninit long han bilong Selomit, na bilong ol brata bilong em.',
        29: '¶ Bilong ol lain Ishar, Kenanaia na ol pikinini man bilong en em i bilong dispela wok ausait long bosim Isrel, bilong ol ofisa na ol jas.',
        30: 'Na bilong ol lain Hibron, Hasabaia na ol brata bilong em, ol strongpela man bilong pait 1,700, em ol ofisa namel long ol bilong Isrel long dispela sait bilong Jordan i go long hap wes long olgeta wok bilong BIKPELA, na long wok bilong king.',
        31: 'Namel long ol lain Hibron em Jeraisa nambawan, yes, namel long ol lain Hibron, bilong bihainim ol lain tumbuna bilong ol tumbuna papa bilong em. Long namba 40 yia bilong Devit i bosim kingdom ol i painim ol, na ol i lukim namel long ol ol strongpela man tru bilong pait long Jaser bilong Gileat.',
        32: 'Na ol brata bilong em, ol strongpela man bilong pait, em 2,700 ol nambawan papa, husat king Devit i mekim i kamap ol hetman long bosim ol lain Ruben, ol lain Gat, na hap lain bilong Manasa, bilong olgeta wan wan samting long sait bilong God, na long ol samting bilong king.',
    },
    27: {
        1: '¶ Nau ol pikinini bilong Isrel i bihainim namba bilong ol, em i olsem, ol nambawan papa na ol kepten bilong ol tausen na ol handret, na ol ofisa bilong ol husat i bihainim king long wanpela samting long taim bilong wok, husat i kam insait na i go ausait, olgeta wan wan mun, long olgeta hap bilong olgeta mun bilong yia, bilong olgeta wan wan taim bilong wok, em 24,000.',
        2: 'Long bosim namba wan taim bilong wok bilong namba wan mun em Jasobeam, pikinini man bilong Sapdiel. Na long taim bilong wok bilong en em 24,000.',
        3: 'Bilong ol pikinini bilong Peres em i nambawan bilong olgeta kepten bilong ami long namba wan mun.',
        4: 'Na long bosim taim bilong wok bilong namba tu mun em Dodai, wanpela man Ahoa, na bilong taim bilong wok bilong en em Miklot tu, hetman. long taim bilong wok bilong em wankain olsem em 24,000.',
        5: 'Namba tri kepten bilong ami bilong namba tri mun em Benea, pikinini man bilong Jehoiada, wanpela hetpris. Na long taim bilong wok bilong en em 24,000.',
        6: 'Dispela em i dispela Benea, husat em i strongpela namel long dispela 30, na antap long dispela 30. Na long taim bilong wok bilong em em Amisabat, pikinini man bilong em.',
        7: 'Namba foa kepten bilong namba foa mun em i Asahel, brata bilong Joap, na Sebadaia, pikinini man bilong em bihain long em. Na long taim bilong wok bilong en em 24,000.',
        8: 'Namba faiv kepten bilong namba faiv mun em man Isra Samhut. Na long taim bilong wok bilong em em 24,000.',
        9: 'Namba sikis kepten bilong namba sikis mun em Ira, pikinini man bilong man Tekoa Ikes. Na long taim bilong wok bilong em em 24,000.',
        10: 'Namba seven kepten bilong namba seven mun em man Pelon Heles, bilong ol pikinini bilong Ifraim. Na long taim bilong wok bilong em em 24,000.',
        11: 'Namba et kepten bilong namba et mun em man Husa Sibekai, bilong ol lain Sara. Na long taim bilong wok bilong em em 24,000.',
        12: 'Namba nain kepten bilong namba nain mun em man Anatot Abieser, bilong ol lain Benjamin. Na long taim bilong wok bilong em em 24,000.',
        13: 'Namba ten kepten bilong namba ten mun em man Netofa Mahari, bilong ol lain Sara. Na long taim bilong wok bilong em em 24,000.',
        14: 'Namba 11 kepten bilong namba 11 mun em man Pirat Benea, bilong ol pikinini bilong Ifraim. Na long taim bilong wok bilong em em 24,000.',
        15: 'Namba 12 kepten bilong namba 12 mun em man Netofa Heldai, bilong Otniel. Na long taim bilong wok bilong em em 24,000.',
        16: '¶ Na moa tu long bosim ol lain bilong Isrel, hetman bilong ol lain Ruben em Eleasar, pikinini man bilong Sikri, bilong ol lain Simion, Sefataia, pikinini man bilong Meaka,',
        17: 'Bilong ol lain Livai, Hasabaia, pikinini man bilong Kemuel, bilong ol lain Eron, Sedok,',
        18: 'Bilong Juda, Elihu, wanpela bilong ol brata bilong Devit, bilong Isakar, Omri, pikinini man bilong Maikel,',
        19: 'Bilong Sebyulun, Ismea, pikinini man bilong Obadaia, bilong Naptalai, Jerimot, pikinini man bilong Asriel,',
        20: 'Bilong ol pikinini bilong Ifraim, Hosea, pikinini man bilong Asasaia, bilong hap lain bilong Manasa, Joel, pikinini man bilong Pedea,',
        21: 'Bilong hap lain bilong Manasa i stap long Gileat, Ido, pikinini man bilong Sekaraia, bilong Benjamin, Jeasiel, pikinini man bilong Apner,',
        22: 'Bilong Dan, Asarel, pikinini man bilong Jeroham. Ol dispela em ol hetman bilong ol lain bilong Isrel.',
        23: 'Tasol Devit i no kisim namba bilong ol i stat long 20 krismas i go aninit. Bilong wanem, BIKPELA i bin tok Em bai mekim Isrel i kamap planti moa olsem ol sta bilong ol heven.',
        24: 'Joap, pikinini man bilong Seruaia, i stat long kaunim ol, tasol em i no pinisim, bilong wanem, belhat tru i pundaun i birua long Isrel long samting. Na tu namba ol i no putim long stori bilong ol stori bilong king Devit.',
        25: 'Na long bosim ol samting i dia tru bilong king em Asmavet, pikinini man bilong Adiel. Na long bosim ol haus bilong putim kago long ol bikpela gaden, long ol biktaun, na long ol vilis, na long ol haus king, em Jehonatan, pikinini man bilong Usaia.',
        26: 'Na long bosim ol husat i mekim wok bilong brukim graun bilong ol bikpela gaden em Esri, pikinini man bilong Kelup.',
        27: 'Na long bosim ol gaden wain em man Rama Simei. Long bosim ol win kaikai bilong ol gaden wain bilong ol bakstua wain em man Sifma Sapdi.',
        28: 'Na long bosim ol diwai oliv na ol diwai sikamor, dispela i stap long ol ples stret i daunbilo, em man Geder Beal-hanan. Na long bosim ol bakstua wel em Joas.',
        29: 'Na long bosim ol lain bulmakau husat i kaikai long Saron em man Saron Sitrai. Na long bosim ol lain bulmakau, dispela i stap long ol ples daun, em Safat, pikinini man bilong Adlai.',
        30: 'Long bosim ol kemel tu em man Ismael Obil. Na long bosim ol donki em man Meron Jedeaia.',
        31: 'Na long bosim ol lain sipsip em man Hager Jasis. Olgeta dispela em ol hetman bilong ol kago, dispela i bilong king Devit.',
        32: 'Na tu Jonatan, smolpapa bilong Devit, em i wanpela man bilong givim tok helpim, wanpela saveman tru, na wanpela man bilong rait. Na Jehiel, pikinini man bilong Hakmoni, em i stap wantaim ol pikinini man bilong king.',
        33: 'Na Ahitofel em man bilong givim tok helpim long king. Na man Ark Husai em poroman bilong king.',
        34: 'Na bihain long Ahitofel em Jehoiada, pikinini man bilong Benea, na Abaiatar. Na jeneral bilong ami bilong king em Joap.',
    },
    28: {
        1: '¶ Na Devit i bungim olgeta hetman bilong Isrel, ol hetman bilong ol lain, na ol kepten bilong ol liklik ami husat i wokim wok long king long taim bilong wok, na ol kepten long bosim ol tausen, na ol kepten long bosim ol handret, na ol man bilong lukautim samting i bosim olgeta kago na samting king i holimpas, na bilong ol pikinini man bilong em, wantaim ol ofisa, na wantaim ol strongpela man, na wantaim olgeta strongpela man bilong pait, i go long Jerusalem.',
        2: 'Nau king Devit i sanap antap long tupela lek bilong em, na tok, Harim mi, ol brata bilong mi, na ol lain manmeri bilong mi. Long sait bilong mi, Mi gat insait long bel bilong mi bilong wokim wanpela haus bilong malolo bilong bokis bilong kontrak bilong BIKPELA, na wanpela liklik sia bilong putim lek bilong God bilong yumi, na mi bin redim ol samting bilong wokim haus.',
        3: 'Tasol God i tokim mi, Yu no ken wokim wanpela haus bilong nem bilong Mi, bilong wanem, yu bin stap wanpela man bilong bikpela pait, na yu bin kapsaitim blut.',
        4: 'Tasol God BIKPELA bilong Isrel i makim mi bipo long olgeta hauslain bilong tumbuna papa bilong mi bilong stap king long bosim Isrel oltaim oltaim. Long wanem, Em i bin makim Juda bilong stap hetman, na bilong hauslain bilong Juda, hauslain bilong papa bilong mi. Na namel long ol pikinini man bilong papa bilong mi, Em i laikim mi bilong mekim mi king long bosim olgeta Isrel.',
        5: 'Na bilong olgeta pikinini man bilong mi, (long wanem, BIKPELA i bin givim mi planti pikinini man,) Em i bin makim Solomon, pikinini man bilong mi, bilong sindaun antap long sia king bilong kingdom bilong BIKPELA long bosim Isrel.',
        6: 'Na Em i tokim mi, Solomon, pikinini man bilong yu, em bai wokim haus bilong Mi na ol ples op bilong Mi. Long wanem, Mi bin makim em bilong stap pikinini man bilong Mi, na Mi bai stap Papa bilong em.',
        7: 'Na moa tu Mi bai strongim kingdom bilong em oltaim oltaim, sapos em i no senis bilong mekim ol tok strong na ol kot bilong Mi, olsem long tude.',
        8: 'Olsem na nau long ai bilong olgeta Isrel, bung bilong ol manmeri bilong BIKPELA, na long ia bilong God bilong yumi, holimpas na painim long olgeta tok strong bilong BIKPELA, God bilong yupela, inap long yupela ken holimpas dispela gutpela hap, na lusim dispela bilong wanpela samting papa i givim pikinini long ol pikinini bilong yupela bihain long yupela oltaim oltaim.',
        9: 'Na yu, Solomon, pikinini man bilong mi, yu mas save long God bilong papa bilong yu, na bihainim em wantaim wanpela bel i inap tru na wantaim wanpela tingting i gat laik. Long wanem, BIKPELA i painim tru long olgeta bel, na Em i gat gutpela save long olgeta tingting nating bilong olgeta tingting. Sapos yu painim Em, Em bai larim yu painim Em pinis. Tasol sapos yu givim baksait long Em, Em bai tromoi yu i go oltaim oltaim.',
        10: 'Was gut nau. Long wanem, BIKPELA i bin makim yu bilong wokim wanpela haus bilong rum holi. Stap strong, na mekim dispela.',
        11: '¶ Nau Devit i givim long Solomon, pikinini man bilong em, plen bilong veranda, na bilong olgeta haus bilong en, na bilong ol bakstua mani bilong en, na bilong ol rum antap bilong en, na bilong ol rum insait bilong en, na bilong ples bilong sia marimari,',
        12: 'Na plen bilong olgeta samting em i bin kisim long Spirit, bilong ol ples op bilong haus bilong BIKPELA, na bilong olgeta rum raun nabaut, bilong ol bakstua mani bilong haus bilong God, na bilong ol bakstua mani bilong ol samting ol i makim.',
        13: 'Na tu plen bilong ol taim bilong wok bilong ol pris na ol lain Livai, na bilong olgeta wok bilong wok bilong haus bilong BIKPELA, na bilong olgeta sospen samting bilong wok bilong haus bilong BIKPELA.',
        14: 'Em i givim bilong gol long hevi bilong en bilong ol samting bilong gol, bilong olgeta samting bilong olgeta kain kain wok, silva tu bilong ol samting bilong silva long hevi bilong en, bilong olgeta samting bilong olgeta wan wan kain wok.',
        15: 'Yes, long hevi bilong en bilong ol stik kandel bilong gol, na bilong ol lam gol bilong ol, long hevi bilong ol bilong olgeta wan wan stik kandel, na bilong ol lam bilong en. Na bilong ol stik kandel silva long hevi bilong ol, bilong stik kandel, na tu bilong ol lam bilong en wantaim, bilong bihainim wok bilong olgeta wan wan stik kandel.',
        16: 'Na long hevi bilong en, em i givim gol bilong ol tebol bilong bret bilong soim, bilong olgeta wan wan tebol. Na wankain olsem em i givim silva bilong ol tebol bilong silva.',
        17: 'Na tu gol i klin tru bilong ol huk bilong mit, na ol dis, na ol kap. Na bilong ol traipela dis gol em i givim gol long hevi bilong en bilong olgeta wan wan traipela dis. Na wankain olsem em i givim silva long hevi bilong en bilong olgeta wan wan traipela dis silva.',
        18: 'Na bilong alta bilong insens gol i klin long hevi bilong en, na gol bilong plen bilong karis bilong ol serupim, dispela i opim i go ausait ol wing bilong ol, na karamapim bokis bilong kontrak bilong BIKPELA.',
        19: 'Olgeta dispela, Devit i tok, BIKPELA i mekim mi long kisim gutpela save long en long rait bilong han bilong En antap long mi, yes, olgeta wok bilong dispela plen.',
        20: 'Na Devit i tokim Solomon, pikinini man bilong em, Stap strong na holimpas gutpela strong bilong pait, na mekim dispela. No ken pret, o wari planti. Long wanem, God BIKPELA, yes, God bilong mi, bai stap wantaim yu. Em bai i no inap fel long helpim yu, o givim baksait long yu, inap long yu bin pinisim olgeta wok bilong wok bilong haus bilong BIKPELA.',
        21: 'Na, lukim, ol taim bilong wok bilong ol pris na ol lain Livai, yes, ol bai stap wantaim yu bilong olgeta wok bilong haus bilong God. Na bai i gat wantaim yu bilong olgeta kain kain gutpela wok, olgeta wan wan man i gat bel na save bilong wokim gutpela wok, bilong olgeta wan wan kain wok. Na tu ol hetman na olgeta lain manmeri bai stap olgeta long tok strong bilong yu.',
    },
    29: {
        1: '¶ Na moa tu king Devit i tokim olgeta bung bilong ol manmeri, Solomon, pikinini man bilong mi, husat em wanpela God i bin makim, em i yangpela yet na em i no strong, na wok em i bikpela. Long wanem, haus king em i no bilong man, tasol em i bilong God BIKPELA.',
        2: 'Nau mi bin redim wantaim olgeta strong bilong mi, bilong haus bilong God bilong mi, gol bilong ol samting ol bai wokim bilong gol, na silva bilong ol samting bilong silva, na bras bilong ol samting bilong bras, na ain bilong ol samting bilong ain, na diwai bilong ol samting bilong diwai, ol ston oniks, na ol ston ol bai putim, ol ston i lait, na bilong kain kain kala, na olgeta kain kain ston i dia tumas, na ol ston marbel i planti moa yet.',
        3: 'Na moa tu, bikos mi bin putim laik bilong bel bilong mi long haus bilong God bilong mi, mi gat bilong ol gutpela samting bilong mi yet, bilong gol na silva, dispela mi bin givim i go long haus bilong God bilong mi, antap na antap long olgeta samting mi bin redim bilong haus holi,',
        4: 'Yes, 3,000 talen bilong gol, bilong gol bilong Ofir, na 7,000 talen bilong silva i klin, bilong karamapim ol banis bilong ol haus wantaim ol dispela olgeta.',
        5: 'Gol bilong ol samting bilong gol, na silva bilong ol samting bilong silva, na bilong olgeta kain kain wok ol bai wokim long ol han bilong ol man i gat save long wokim samting. Na husat nau em i gat bel bilong mekim wok bilong em i kamap holi tude i go long BIKPELA?',
        6: 'Nau ol nambawan bilong ol papa na ol hetman bilong olgeta lain bilong Isrel, na ol kepten bilong ol tausen na bilong ol handret, wantaim ol hetman bilong wok bilong king, i givim ofa wantaim bel,',
        7: 'Na givim bilong wok bilong haus bilong God bilong gol 5,000 talen na 10,000 dram, na bilong silva 10,000 talen, na bilong bras 18,000 talen, na 100,000 talen ain.',
        8: 'Na long ol husat i gat ol ston i dia tumas, ol i givim ol long samting i dia tru bilong haus bilong BIKPELA, long han bilong man Gerson Jehiel.',
        9: 'Nau ol manmeri i wokim amamas tru, long wanem, ol i givim ofa wantaim bel, bilong wanem, wantaim bel i inap tru ol i givim ofa wantaim bel i go long BIKPELA. Na king Devit tu i wokim amamas tru wantaim bikpela amamas tru.',
        10: '¶ Olsem na Devit i blesim BIKPELA long ai bilong olgeta bung bilong ol manmeri. Na Devit i tok, Blesing i stap long Yu, God BIKPELA bilong Israel, tumbuna papa bilong mipela, oltaim oltaim na oltaim.',
        11: 'Bilong Yu, O BIKPELA, em bikpela nem, na pawa, na glori, na winim pait, na biknem tru. Long wanem, olgeta samting i stap long heven na long dispela graun em i bilong Yu. Kingdom em i bilong Yu, O BIKPELA, na Yu stap God husat mipela litimapim olsem het i antap long olgeta.',
        12: 'Ol planti mani samting na biknem wantaim i kam long Yu, na Yu bosim kingdom antap long olgeta. Na long han bilong Yu em pawa na strong. Na long han bilong Yu em i stap bilong mekim bikpela, na bilong givim strong long olgeta.',
        13: 'Olsem na nau, God bilong mipela, mipela tok tenkyu long Yu, na litimapim nem bilong Yu i gat glori.',
        14: 'Tasol mi husat, na lain manmeri bilong mi i wanem, inap long mipela ken stap inap long wokim ofa wantaim bel olsem i bihainim dispela kain? Long wanem, olgeta samting i kam long Yu, na bilong samting bilong Yu yet mipela bin givim long Yu.',
        15: 'Long wanem, mipela stap ol ausait man long ai bilong Yu, na ol waira, olsem olgeta tumbuna papa bilong mipela. Ol de bilong mipela antap long dispela graun i stap olsem wanpela tewel bilong san, na i no gat pasin bilong wanpela i stap.',
        16: 'O BIKPELA, God bilong mipela, olgeta dispela kago, dispela mipela bin redim bilong wokim long Yu wanpela haus bilong nem holi bilong Yu, i kam long han bilong Yu, na olgeta em i bilong Yu Yet.',
        17: 'Mi save tu, God bilong Mi, long Yu save traim bel, na Yu gat amamas long stretpela pasin. Long sait bilong mi, long stretpela pasin bilong bel bilong mi, mi bin wokim ofa wantaim bel, olgeta dispela samting. Na nau mi bin lukim wantaim amamas tru ol manmeri bilong Yu, husat i stap hia, long wokim ofa wantaim bel i go long Yu.',
        18: 'O God BIKPELA bilong Ebraham, Aisak, na bilong Isrel, ol tumbuna papa bilong mipela, holimpas dispela bilong oltaim oltaim insait long tingting nating bilong ol tingting bilong bel bilong lain manmeri bilong Yu, na redim bel bilong ol i go long Yu.',
        19: 'Na givim long Solomon, pikinini man bilong mi, wanpela bel i inap tru, bilong holimpas ol tok strong bilong Yu, ol testimoni bilong Yu, na ol lo Yu raitim bilong Yu, na bilong mekim olgeta dispela samting, na bilong wokim haus king, dispela mi bin redim ol samting bilong en.',
        20: 'Na Devit i tokim olgeta bung bilong ol manmeri, Nau blesim BIKPELA, God bilong yupela. Na olgeta bung bilong ol manmeri i blesim BIKPELA, God bilong ol tumbuna papa bilong ol, na lindaunim ol het bilong ol, na lotuim BIKPELA, na king.',
        21: 'Na ol i ofaim ol sakrifais i go long BIKPELA, na ofaim ol ofa i kuk olgeta i go long BIKPELA, long moning bihain long dispela de, yes, wan tausen bulmakau man, wan tausen sipsip man, na wan tausen pikinini sipsip, wantaim ol ofa bilong dring bilong ol, na ol sakrifais i planti moa yet bilong olgeta Isrel.',
        22: 'Na ol i bin kaikai na dring long ai bilong BIKPELA long dispela de wantaim bikpela amamas. Na ol i mekim Solomon, pikinini man bilong king Devit, king namba tu taim, na makim em i go long BIKPELA bilong stap nambawan nambawan gavman, na Sedok bilong stap pris.',
        23: '¶ Nau Solomon i sindaun antap long sia king bilong BIKPELA olsem king i kisim ples bilong Devit, papa bilong em, na em i kamap gutpela. Na olgeta Isrel i bihainim tok bilong em.',
        24: 'Na olgeta hetman, na ol strongpela man, na wankain olsem olgeta pikinini man bilong king Devit, i putim ol yet aninit long king Solomon.',
        25: 'Na BIKPELA i litimapim nem bilong Solomon planti moa yet long ai bilong olgeta Isrel. Na Em i putim antap long em kain biknem tru bilong king olsem i no bin stap antap long wanpela king bipo long em long Isrel.',
        26: 'Olsem tasol Devit, pikinini man bilong Jesi, i bosim kingdom antap long olgeta Isrel.',
        27: 'Na taim long em i bosim kingdom antap long Isrel em 40 yia. Sevenpela yia em i bosim kingdom long Hibron, na 33 yia em i bosim kingdom long Jerusalem.',
        28: 'Na em i dai pinis taim em i stap lapun tru, pulap long ol de, ol planti mani samting, na biknem. Na Solomon, pikinini man bilong em, i kisim ples bilong em na bosim kingdom.',
        29: 'Nau ol wok bilong king Devit, namba wan na las, lukim, ol i raitim ol insait long buk bilong sia Samyuel, na insait long buk bilong profet Netan, na insait long buk bilong sia Gat,',
        30: 'Wantaim olgeta pasin bilong em long bosim kingdom na strong bilong em, na ol taim, dispela i go antap long em, na antap long Isrel, na antap long olgeta kingdom bilong ol kantri.',
    },
}
